window.VB_DATA=window.VB_DATA||{};VB_DATA.pt=[
["que","","that / which / what","kee","SOM","Say \"KEY\" without the y: the little word that unlocks every clause. Eu acho que... = I think that...","Acho que vai chover hoje.","I think it's going to rain today."],
["a","","the (feminine) / to / her","ah","REGRA","The same \"ah\" you say at the doctor's. Before feminine nouns it means the: a casa, a mesa.","Ela abriu a janela da sala.","She opened the living room window."],
["o","","the (masculine) / him / it","oo","REGRA","Written o, but unstressed it sounds like the \"oo\" in boot. Before masculine nouns: o carro, o livro.","O ônibus chegou atrasado de novo.","The bus arrived late again."],
["não","","no / not","nown (nasal, like 'now' with a hum)","SOM","Say NOW while pinching your nose: that nasal ão is the sound of refusal. It goes before the verb: não sei.","Não gosto de café sem açúcar.","I don't like coffee without sugar."],
["de","","of / from","jee (d before an ee sound becomes j)","REGRA","Brazilians turn de into \"jee\", like the start of jeep. Copo de água = glass of water; sou de Recife = I'm from Recife.","Ela é de Porto Alegre.","She is from Porto Alegre."],
["esse","","this / that (near you)","ES-see","EN","Point at the thing in your listener's hand and hiss \"S-S\": esse livro, that book near you. Feminine: essa.","Esse casaco é seu?","Is that jacket yours?"],
["e","","and","ee","IMG","A tiny \"ee\" squeaking between two things, like a plus sign: arroz e feijão, rice and beans.","Quero arroz e feijão, por favor.","I'd like rice and beans, please."],
["um","","a / an / one (masculine)","oong (nasal, lips closed at the end)","SOM","Say \"oom\" and hum it through the nose, lips shut. One finger up: um café.","Me vê um pão de queijo?","Can I get a cheese bread?"],
["para","","for / to / in order to","PAH-rah (casually 'prah')","FRASE","A bus sign reading PARA CENTRO tells you where it goes: toward downtown. Spoken fast it shrinks to \"pra\".","Esse presente é para você.","This gift is for you."],
["eu","","I","EH-oo","SOM","\"EH-oo\", like the start of the English ew, but cheerful. You raise your hand: eu!","Eu moro perto da praia.","I live near the beach."],
["uma","","a / an / one (feminine)","OO-mah","PAD","Add -a to um and you get the feminine version: uma casa, uma ideia. Counting: uma, duas, três.","Ela comprou uma bicicleta nova.","She bought a new bicycle."],
["nosso","","our / ours","NOS-soo","LA","Latin noster, the one in Pater Noster (Our Father). Feminine: nossa, which also works as Wow!","Nosso apartamento fica no terceiro andar.","Our apartment is on the third floor."],
["com","","with","kong (nasal)","LA","Latin cum, as in summa cum laude. Café com leite = coffee with milk, the classic Brazilian breakfast.","Vou ao cinema com minha irmã.","I'm going to the movies with my sister."],
["se","","if / oneself","see","ES","Spanish si, sounding just like English \"see\": if you see it, you believe it. Also the reflexive se.","Se chover, a gente fica em casa.","If it rains, we'll stay home."],
["do","","of the (masculine)","doo","REGRA","de + o glued together = do. O carro do João = John's car (the car of the John).","A porta do quarto está fechada.","The bedroom door is closed."],
["por","","by / through / for / per","poh (soft r at the end)","LA","Latin per, as in per hour: por hora. Também: by, through, because of, thanks for.","Obrigado por tudo.","Thanks for everything."],
["os","","the (masculine plural)","oos","REGRA","o + s = os, the plural label: os meninos, os livros. Mixed groups also take os.","Os meninos estão jogando bola.","The boys are playing soccer."],
["ele","","he / him","EH-lee","SOM","\"EH-lee\" sounds like Ellie, but it means HE. Feminine partner: ela.","Ele trabalha num banco.","He works at a bank."],
["mas","","but","mahs (often 'mice')","SOM","\"Mice\"? I wanted cheese, BUT the mice ate it. Brazilians often say \"mice\" for mas.","Quero ir, mas estou cansado.","I want to go, but I'm tired."],
["em","","in / on / at","eng (nasal, ends like 'sing')","LA","Latin in became em, nasalized. Em casa = at home, em cima = on top.","Ela está em casa agora.","She's at home now."],
["bem","","well / very","beng (nasal)","LA","Latin bene, as in benefit and benevolent. Tudo bem? = all good? Bem cedo = very early.","Dormi bem esta noite.","I slept well last night."],
["isso","","that / this (thing near you)","EE-soo","SOM","\"EE-soo!\" Brazilians shout isso! meaning exactly, that's it! Points to the thing you just mentioned.","Isso é muito caro.","That is very expensive."],
["da","","of the (feminine)","dah","REGRA","de + a = da. A casa da Maria = Maria's house. The feminine twin of do.","A chave da casa sumiu.","The house key disappeared."],
["como","","how / like / as","KOH-moo","ES","Spanish ¿cómo?, same spelling. Como vai? = How's it going? Also as: como sempre, as always.","Como você chegou aqui?","How did you get here?"],
["sim","","yes","sing (nasal, the g is barely heard)","LA","Latin sic (thus, so), shortened and nasalized. Brazilians usually answer by repeating the verb instead: Quer? Quero!","Sim, pode entrar.","Yes, you can come in."],
["as","","the (feminine plural)","ahs","REGRA","a + s = as: as casas, as mulheres. Easy to tell apart from os by the vowel.","As lojas abrem às nove.","The stores open at nine."],
["no","","in the / on the (masculine)","noo","FALSO","NOT English no! It's em + o: no carro = in the car. To say no, use não.","As chaves estão no carro.","The keys are in the car."],
["mais","","more / most / plus","mice (rhymes with 'nice')","LA","Latin magis. Pronounced like \"mice\": more mice, more problems. Mais ou menos = more or less.","Quero mais um pedaço de bolo.","I want one more piece of cake."],
["na","","in the / on the (feminine)","nah","FALSO","Not \"nah\" as in no! It's em + a: na praia = on the beach, na rua = in the street.","Ela está esperando na esquina.","She's waiting on the corner."],
["meu","","my / mine (masculine)","MEH-oo","SOM","A cat says \"MEH-oo\" and claims everything: MY sofa, MY bed. Meu Deus! = My God!","Meu irmão mora em Curitiba.","My brother lives in Curitiba."],
["aqui","","here","ah-KEE","SOM","\"Ah, KEY!\" You found your keys right HERE. Spanish speakers: same as aquí.","Pode deixar a mala aqui.","You can leave the suitcase here."],
["muito","","very / a lot / much","MOOY-toong (nasal, the n is hidden)","LA","Latin multum, as in multiply. It hides a nasal sound: say \"MOOY-too\" through the nose. Muito obrigado!","Muito obrigado pela ajuda.","Thank you very much for the help."],
["outro","","other / another","OH-troo","LA","Latin alter, as in alternative: the OTHER option. Outro café? = Another coffee?","Quer outro copo de suco?","Do you want another glass of juice?"],
["ela","","she / her","EH-lah","NOME","Ella Fitzgerald: ELA is a SHE. Masculine partner: ele.","Ela fala três línguas.","She speaks three languages."],
["isto","","this (thing here)","EES-too","LA","Latin istud. The T points closer than isso: isto is the thing in MY hand.","O que é isto aqui?","What is this here?"],
["algum","","some / any (masculine)","ow-GOONG (l at end of syllable sounds like w)","PAD","Al- + gum: like a piece of gum, SOME is in your pocket. Feminine: alguma.","Você tem algum dinheiro trocado?","Do you have any small change?"],
["fazer","","to do / to make","fah-ZEH (soft r)","LA","Latin facere, as in factory and fact: things are MADE there. Fazer café, fazer compras.","Vou fazer um bolo de chocolate.","I'm going to make a chocolate cake."],
["aquele","","that (over there)","ah-KEH-lee","SOM","\"Ah, KELLY!\" you shout, pointing at that girl way over there. Farther away than esse.","Aquele prédio é um hotel.","That building over there is a hotel."],
["já","","already / right now","zhah (s as in 'measure')","SOM","\"ZHA!\" like ta-da: it's ALREADY done. Já volto = I'll be right back.","Já terminei o trabalho.","I already finished the work."],
["ser","","to be (permanent)","seh (soft r, almost silent)","FRASE","Hamlet in Portuguese: Ser ou não ser. Use ser for who or what something is; estar for states.","Quero ser médica um dia.","I want to be a doctor one day."],
["qual","","which / what","kwow (rhymes with 'now')","LA","Latin qualis, as in quality: WHICH kind? Qual é o seu nome? = What's your name?","Qual é a sua cor favorita?","What is your favorite color?"],
["à","","to the (feminine)","ah (said a little longer)","REGRA","a + a melt into one à, marked with a grave accent. Vou à praia = I'm going to the beach.","Amanhã vamos à praia cedo.","Tomorrow we're going to the beach early."],
["minha","","my / mine (feminine)","MEEN-yah","PAD","meu for him, minha for her: minha mãe, minha casa. nh sounds like the ny in canyon.","Minha mãe faz o melhor bolo.","My mom makes the best cake."],
["só","","only / just / alone","saw","SOM","Sounds like \"saw\": I SAW ONLY one. Também: estou só = I'm alone. Só um minuto!","Só tenho dez reais.","I only have ten reais."],
["ao","","to the (masculine)","ow","REGRA","a + o = ao, said \"ow\". Vou ao médico = I'm going to the doctor.","Preciso ir ao banco hoje.","I need to go to the bank today."],
["alguém","","someone / anyone","ow-GANG (nasal end)","PAD","Al- (some) + -guém (from quem, who): some-who = someone. Tem alguém aí?","Alguém deixou a porta aberta.","Someone left the door open."],
["tudo","","everything / all","TOO-doo","SOM","\"TOO-DOO\" list: EVERYTHING on it. Tudo bem? = Everything good? is the standard Brazilian hello.","Tudo bem com você?","Is everything OK with you?"],
["te","","you (object) / to you","chee (t before an ee sound becomes ch)","REGRA","In Brazil te sounds like \"chee\" and goes before the verb: Te amo = I love you.","Te ligo mais tarde.","I'll call you later."],
["porque","","because","poh-KEH","PAD","por (for) + que (what): for what reason? Because! Written together for because, apart (por que) for why.","Fiquei em casa porque estava chovendo.","I stayed home because it was raining."],
["haver","","there to be / to have (formal)","ah-VEH (h is silent)","EN","have → haver, h silent. Its form há means there is / there are: há um problema.","Vai haver uma festa no sábado.","There's going to be a party on Saturday."],
["oi","","hi / hello","oy","SOM","Just like \"oy!\" to get a friend's attention: the everyday Brazilian hello. Answer: Oi, tudo bem?","Oi, tudo bem com você?","Hi, how are you doing?"],
["entre","","between / among","EN-tree","FR","French entre, same spelling: entre nous, between us. Entre! also means Come in!","A farmácia fica entre o banco e a padaria.","The pharmacy is between the bank and the bakery."],
["tu","","you (informal, regional)","too","LA","Latin tu, Shakespeare's thou. Common in the South and Northeast of Brazil; elsewhere people say você.","Tu vais à festa hoje?","Are you going to the party today?"],
["antes","","before","AN-cheess","EN","Ante- as in anteroom: the room BEFORE the room. t before i-sound becomes ch: \"AN-chees\".","Lave as mãos antes do almoço.","Wash your hands before lunch."],
["quando","","when","KWAN-doo","LA","Latin quando, used in Italian and Spanish too. Picture a clock with a question mark: quando?","Quando você volta de viagem?","When do you come back from your trip?"],
["agora","","now","ah-GOH-rah","IMG","AGORA sounds like the Greek agora, the marketplace where everything happens right NOW. Agora não! = Not now!","Agora não posso falar.","I can't talk now."],
["tchau","","bye","chow","IT","From Italian ciao, respelled the Brazilian way. Rhymes with \"wow\": tchau, tchau!","Tchau, até amanhã!","Bye, see you tomorrow!"],
["você","","you","voh-SEH","PAD","Shortened from Vossa Mercê, Your Grace: a polite title that became everyday YOU. Takes the he/she verb: você é.","Você quer um café?","Do you want a coffee?"],
["lá","","there (over there)","lah","SOM","Sing \"la la la\" toward the far mountain: lá is THERE, far away. Lá em casa = at my place.","Vamos lá agora mesmo.","Let's go there right now."],
["então","","so / then","en-TOWNG (nasal end)","SOM","Stretch it out like \"so...\" while thinking: entããão... Brazilians start stories with it.","Então, o que vamos fazer hoje?","So, what are we doing today?"],
["ter","","to have","teh (soft r)","LA","Latin tenere, as in tenant: someone who HAS a place. Eu tenho, você tem.","Você precisa ter paciência.","You need to have patience."],
["algo","","something","OW-goo","ES","Same word in Spanish. Algo mais? = Anything else? asks every waiter.","Quer comer algo antes do filme?","Do you want to eat something before the movie?"],
["quem","","who / whom","keng (nasal)","LA","Latin quem, the whom form. Quem é? = Who is it? at the door.","Quem ligou para você?","Who called you?"],
["onde","","where","ON-jee","LA","Latin unde (from where). The d before i-sound becomes j: \"ON-jee\". Onde fica? = Where is it?","Onde fica o banheiro?","Where is the bathroom?"],
["nada","","nothing / you're welcome (de nada)","NAH-dah","EN","English borrowed it: zip, zero, nada. De nada = it was nothing, you're welcome.","Não tem nada na geladeira.","There's nothing in the fridge."],
["ou","","or","oh","FR","French ou, same spelling. Café ou chá? = Coffee or tea?","Prefere praia ou montanha?","Do you prefer the beach or the mountains?"],
["coisa","f","thing","KOY-zah","LA","Latin causa (a matter, a case) wore down into coisa. Uma coisa = a thing; coisa nenhuma = nothing at all.","Tenho uma coisa para te contar.","I have something to tell you."],
["dizer","","to say / to tell","jee-ZEH (soft r)","LA","Latin dicere, as in dictate and diction. Quer dizer = it means (it wants to say).","O que você quer dizer com isso?","What do you mean by that?"],
["nenhum","","no / none / not any","nee-NYOONG (nasal)","LA","Latin nec unum, not even one. Nenhum problema = no problem at all.","Não tenho nenhum plano para hoje.","I don't have any plans for today."],
["desde","","since / from","DEZ-jee","ES","Spanish desde, same word. Desde 2010 = since 2010. Desde criança = since childhood.","Moro aqui desde 2015.","I've lived here since 2015."],
["procurar","","to look for / to search","proh-koo-RAH","EN","procure → procurar: to obtain by searching. Estou procurando = I'm looking for.","Vou procurar um apartamento perto do trabalho.","I'm going to look for an apartment near work."],
["vocês","","you (plural) / you all","voh-SEHS","PAD","você + s = vocês: the Brazilian y'all. It takes the they form of the verb: vocês são.","Vocês querem pizza ou hambúrguer?","Do you guys want pizza or a burger?"],
["seu","","your / his / her (masculine)","SEH-oo","PAD","Matches você: o seu carro = your car. Also his or her, so Brazilians often prefer dele / dela for clarity.","Esse é o seu lugar?","Is this your seat?"],
["durante","","during","doo-RAN-chee","EN","during → durante, both from endure: for the whole time. Durante o filme = during the movie.","Dormi durante a viagem inteira.","I slept during the whole trip."],
["mesmo","","same / even / really","MEZ-moo","ES","Spanish mismo. O mesmo = the same; mesmo assim = even so; sério mesmo? = really?","Temos o mesmo sobrenome.","We have the same last name."],
["esta","","this (feminine, near me)","ES-tah","FALSO","Not está (is)! No accent, stress on ES: esta casa = this house. The accented está is a verb.","Esta mesa está livre?","Is this table free?"],
["eles","","they / them (masculine or mixed)","EH-leess","PAD","ele + s = eles: a whole group of HE's. Feminine group: elas.","Eles chegaram ontem à noite.","They arrived last night."],
["nós","","we / us","nawss","LA","Latin nos, as in the Spanish nosotros. Everyday speech often swaps it for a gente.","Nós vamos jantar fora hoje.","We're going out for dinner tonight."],
["sua","","your / his / her (feminine)","SOO-ah","PAD","The feminine form of seu: a sua casa, a sua bolsa. It matches the thing owned, not the owner.","Sua bolsa está na cadeira.","Your bag is on the chair."],
["dos","","of the (masculine plural)","doos","REGRA","de + os = dos. O time dos meninos = the boys' team.","A casa dos meus avós é antiga.","My grandparents' house is old."],
["todo","","all / whole / every","TOH-doo","LA","Latin totus, as in total. Todo dia = every day; o dia todo = the whole day.","Ela corre todo dia de manhã.","She runs every morning."],
["nos","","us / to us / in the (plural)","noos","REGRA","Two jobs: object pronoun (ele nos ajudou = he helped us) and em + os (nos fins de semana = on weekends).","Ele nos convidou para o casamento.","He invited us to the wedding."],
["mim","","me (after prepositions)","ming (nasal)","REGRA","After para, de, sem: para mim = for me. Hum it like \"me\" through the nose.","Esse café é para mim?","Is this coffee for me?"],
["comigo","","with me","koh-MEE-goo","LA","Latin mecum turned inside out: com + migo. Vem comigo! = Come with me!","Você quer ir comigo ao mercado?","Do you want to go to the market with me?"],
["bom","","good","bong (nasal)","FR","French bon, as in bon voyage. Bom dia = good morning. Feminine: boa.","Esse restaurante é muito bom.","This restaurant is very good."],
["ver","","to see","veh (soft r)","LA","Latin videre, as in video and vision. Vamos ver = let's see.","Quero ver esse filme no cinema.","I want to see that movie at the theater."],
["este","","this (masculine, near me)","ES-chee","LA","Latin iste. Like esta, but for masculine nouns: este livro. In speech Brazilians often use esse instead.","Este ano vou aprender a nadar.","This year I'm going to learn to swim."],
["casa","f","house / home","KAH-zah","IT","Casa Blanca is the White House. Em casa = at home; a single s between vowels sounds like z.","Minha casa tem um quintal grande.","My house has a big backyard."],
["dela","","her / hers / of her","DEH-lah","PAD","de + ela = dela: of her. Clearer than sua, so Brazilians say a bolsa dela = her bag.","A bolsa dela ficou no táxi.","Her bag was left in the taxi."],
["desculpa","f","sorry / excuse","jees-KOOL-pah","LA","des- + culpa (guilt, as in culprit): removing the guilt. Desculpa! = Sorry!","Desculpa, cheguei atrasado.","Sorry, I'm late."],
["aquilo","","that (thing over there)","ah-KEE-loo","SOM","\"Ah, kilo!\" Pointing at that big sack over there: what is THAT? Used for things, never people.","O que é aquilo no céu?","What is that in the sky?"],
["nunca","","never","NOON-kah","LA","Latin numquam: not once, ever. Nunca mais = never again.","Nunca comi comida japonesa.","I've never eaten Japanese food."],
["certeza","f","certainty","sehr-TEH-zah","EN","certain → certeza. Tem certeza? = Are you sure? Com certeza! = Absolutely!","Você tem certeza disso?","Are you sure about that?"],
["até","","until / up to / even","ah-TEH","SOM","\"At 8\" sounds like até: wait UNTIL 8. Até logo! = See you soon!","A loja fica aberta até as dez.","The store stays open until ten."],
["assim","","like this / so / that way","ah-SING (nasal)","SOM","\"A-SING\": sing it LIKE THIS. Assim mesmo = just like that.","Faz assim, é mais fácil.","Do it like this, it's easier."],
["dele","","his / of him","DEH-lee","PAD","de + ele = dele: of him. Brazilians love it because it is clearer than seu: o carro dele = his car.","O carro dele quebrou de novo.","His car broke down again."],
["saudade","f","longing / missing someone","sow-DAH-jee","FRASE","The famous untranslatable word: the ache of missing someone. Estou com saudade = I miss you.","Estou com saudade da minha avó.","I miss my grandmother."],
["falar","","to speak / to talk","fah-LAH (soft r)","FR","Parler in French, hablar in Spanish, falar here: fables are things spoken. Fala português?","Você fala inglês?","Do you speak English?"],
["senhora","f","lady / ma'am","seen-YOH-rah","ES","Spanish señora, with nh instead of ñ. A senhora = polite you for an older woman.","A senhora precisa de ajuda?","Do you need help, ma'am?"],
["ainda","","still / yet","ah-EEN-dah","SOM","\"Ah, INDA-ed, it's STILL raining.\" Ainda não = not yet.","Ainda não almocei.","I still haven't had lunch."],
["tempo","m","time / weather","TEM-poo","IT","Musicians know tempo: the TIME of a song. Also weather: o tempo está bom.","Não tenho tempo para almoçar hoje.","I don't have time for lunch today."],
["também","","also / too","tang-BENG (nasal twice)","SOM","Two nasal hums, \"tam-BENG\", like a drum and a bell joining in TOO. Eu também! = Me too!","Eu também quero sorvete.","I want ice cream too."],
["ir","","to go","eer (soft r)","LA","Latin ire, as in exit (ex + ire, go out). Vou, vai, vamos: the forms look nothing alike.","Amanhã preciso ir ao dentista.","Tomorrow I need to go to the dentist."],
["pai","m","father / dad","pie","SOM","Dad loves PIE: pai rhymes with it. Os pais = the parents.","Meu pai cozinha muito bem.","My dad cooks really well."],
["sobre","","about / on top of","SOH-bree","LA","Latin super, as in superior: over, ABOUT. Um livro sobre o Brasil = a book about Brazil.","Vamos conversar sobre isso amanhã.","Let's talk about that tomorrow."],
["vez","f","time (occurrence) / turn","vess","LA","Latin vicis, as in vice-president: the one whose TURN comes next. Uma vez = once; sua vez = your turn.","É a minha vez de pagar.","It's my turn to pay."],
["nem","","nor / not even","neng (nasal)","SOM","\"NANG\", a door slamming: NOT EVEN a chance. Nem eu = me neither.","Ele nem olhou para mim.","He didn't even look at me."],
["ninguém","","nobody / no one","neen-GANG (nasal)","PAD","The opposite of alguém (someone): ninguém, no-who. Ninguém sabe = nobody knows.","Ninguém atendeu o telefone.","Nobody answered the phone."],
["enquanto","","while","en-KWAN-too","PAD","en + quanto (how much): for as long as. Enquanto você dorme = while you sleep.","Ela lê enquanto espera o ônibus.","She reads while she waits for the bus."],
["favor","m","favor","fah-VOH (soft r)","EN","favor → favor, identical. Por favor = please (by favor). Me faz um favor?","Pode me fazer um favor?","Can you do me a favor?"],
["depois","","after / later / then","deh-POYSS","SOM","\"Day-POISE\": first the day, then the poise. Depois a gente vê = we'll see later.","Depois do jantar, vamos ver um filme.","After dinner, we'll watch a movie."],
["tão","","so / such / as","towng (nasal)","SOM","Rhymes with não, but it pumps things up: tão bonito = so pretty. Tão... quanto = as... as.","Você está tão diferente!","You look so different!"],
["melhor","","better / best","meh-LYOH (lh like 'lli' in 'million')","LA","Latin melior, as in ameliorate (make better). O melhor = the best.","Esse é o melhor pastel da feira.","This is the best pastel at the street market."],
["mãe","f","mother / mom","mynh (like 'my' through the nose)","SOM","Say \"MY\" while humming through the nose: MY mom. Dia das Mães = Mother's Day.","Minha mãe mora no interior.","My mom lives in the countryside."],
["talvez","","maybe / perhaps","tow-VESS","PAD","tal (such) + vez (time): at such a time, MAYBE. Talvez amanhã = maybe tomorrow.","Talvez eu chegue um pouco atrasado.","Maybe I'll arrive a bit late."],
["olá","","hello","oh-LAH","ES","Spanish hola, with the stress at the end. A bit more formal than oi.","Olá, posso ajudar?","Hello, can I help you?"],
["obrigado","","thank you (said by a man)","oh-bree-GAH-doo","EN","obliged → obrigado: I'm much obliged. A woman says obrigada.","Obrigado pelo presente!","Thank you for the gift!"],
["noite","f","night / evening","NOY-chee","LA","Latin nox, as in nocturnal and equinox. Boa noite = good evening or good night.","Hoje à noite vamos sair.","Tonight we're going out."],
["ti","","you (after a preposition, with tu)","chee","REGRA","The tu version of mim: para ti = for you. Sounds like \"chee\" because t before i becomes ch.","Comprei isso para ti.","I bought this for you."],
["sempre","","always","SEM-pree","LA","Latin semper, as in the US Marines' Semper Fi (always faithful). Como sempre = as always.","Ela sempre chega no horário.","She always arrives on time."],
["dia","m","day","JEE-ah","LA","Latin dies, as in diary. Masculine despite the -a: o dia, bom dia!","Que dia lindo hoje!","What a beautiful day today!"],
["certo","","right / correct / certain","SEHR-too","EN","certain → certo. Tá certo! = All right! Errado is its opposite.","Você tem o endereço certo?","Do you have the right address?"],
["vida","f","life","VEE-dah","LA","Latin vita, as in vitamin and vital. Minha vida = my life, also a sweet nickname.","A vida no campo é tranquila.","Life in the countryside is peaceful."],
["sem","","without","seng (nasal)","LA","Latin sine, as in sine qua non. Café sem açúcar = coffee without sugar.","Saí de casa sem guarda-chuva.","I left home without an umbrella."],
["estar","","to be (temporary state or place)","es-TAH (soft r)","EN","state → estar: the STATE you are in right now. Estou cansado; ser is for what you are.","Vou estar no escritório até as seis.","I'll be at the office until six."],
["homem","m","man","OH-meng (h silent, nasal end)","LA","Latin homo, as in Homo sapiens. The h is silent.","Aquele homem é o dono da padaria.","That man is the bakery owner."],
["vontade","f","will / desire / urge","von-TAH-jee","LA","Latin voluntas, as in voluntary. Estou com vontade de = I feel like.","Estou com vontade de comer pizza.","I feel like eating pizza."],
["pelo","","by the / through the / for the","PEH-loo","REGRA","por + o = pelo: passear pelo parque = stroll through the park. Obrigado pelo café!","Passamos pelo centro da cidade.","We went through the city center."],
["ficar","","to stay / to become / to be located","fee-KAH (soft r)","IMG","A FIg tree that never moves: it STAYS put. Fica perto = it's nearby; fiquei feliz = I became happy.","Vou ficar em casa hoje.","I'm going to stay home today."],
["tanto","","so much / so many","TAN-too","LA","Latin tantus. Tanto faz = it doesn't matter (either is so much the same).","Nunca vi tanto carro na rua.","I've never seen so many cars on the street."],
["claro","","clear / light / of course","KLAH-roo","EN","clear → claro, as in clarity. Claro! = Of course! Azul claro = light blue.","Claro que você pode vir!","Of course you can come!"],
["verdade","f","truth","vehr-DAH-jee","PAD","-dade = -ty: verity → verdade. É verdade? = Is it true?","Ele sempre fala a verdade.","He always tells the truth."],
["tipo","m","type / kind / like (slang)","CHEE-poo","EN","type → tipo. Teens fill sentences with tipo, exactly like English \"like\".","Que tipo de música você gosta?","What kind of music do you like?"],
["senhor","m","sir / gentleman / Mr.","seen-YOH (soft r)","ES","Spanish señor. O senhor = polite you for an older man.","O senhor quer mais café?","Would you like more coffee, sir?"],
["apenas","","only / just","ah-PEH-nahss","ES","Spanish apenas means barely; here it means ONLY. A bit more formal than só.","Apenas dois alunos faltaram hoje.","Only two students were absent today."],
["trabalho","m","work / job","trah-BAH-lyoo","FR","French travail, as in travel (once hard work). Vou para o trabalho = I'm going to work.","Meu trabalho começa às oito.","My work starts at eight."],
["saber","","to know (facts / how to)","sah-BEH (soft r)","LA","Latin sapere, as in Homo sapiens, the one who KNOWS. Sei nadar = I know how to swim.","Você quer saber um segredo?","Do you want to know a secret?"],
["dinheiro","m","money","jee-NYAY-roo","LA","Latin denarius, the Roman coin that also gave dinar. Dinheiro vivo = cash.","Esqueci o dinheiro em casa.","I forgot the money at home."],
["aí","","there (near you)","ah-EE","SOM","\"Ah-EE!\" yelled at someone over THERE, near you. E aí? = What's up?","Tem alguém aí?","Is anyone there?"],
["pouco","","little / a bit / few","POH-koo","LA","Latin paucus, as in paucity (scarcity). Um pouco = a little.","Fala um pouco mais devagar, por favor.","Speak a little more slowly, please."],
["grande","","big / large / great","GRAN-jee","EN","grand → grande. Grande São Paulo = Greater São Paulo.","Eles moram numa casa grande.","They live in a big house."],
["hoje","","today","OH-zhee (h silent)","LA","Latin hodie, hoc die, on this day. Hoje é sexta! = Today is Friday!","Hoje está muito quente.","It's very hot today."],
["mulher","f","woman / wife","moo-LYEH (soft r)","LA","Latin mulier. Minha mulher = my wife, informally.","A mulher do vizinho é professora.","The neighbor's wife is a teacher."],
["fora","","outside / out","FOH-rah","LA","Latin foris, as in foreign: from outside. Jantar fora = to eat out.","As crianças estão brincando lá fora.","The kids are playing outside."],
["filho","m","son / child","FEE-lyoo","LA","Latin filius, as in filial. Os filhos = the children. Feminine: filha.","Meu filho tem cinco anos.","My son is five years old."],
["cá","","here (to here)","kah","LA","Latin eccum hac. Mainly in set phrases in Brazil: vem cá! = come here! Para cá = over here.","Vem cá, quero te mostrar uma coisa.","Come here, I want to show you something."],
["sério","","serious / seriously","SEH-ree-oo","EN","serious → sério. Sério? = Really? is the classic reaction.","Sério que você nunca viu o mar?","Seriously, you've never seen the sea?"],
["nome","m","name","NOH-mee","LA","Latin nomen, as in nominate. Qual é o seu nome? = What's your name?","Qual é o nome do seu cachorro?","What's your dog's name?"],
["dar","","to give","dah (soft r)","LA","Latin dare, as in donate and data (things given). Dá pra = it's possible.","Vou dar um livro para ela.","I'm going to give her a book."],
["tentar","","to try / to attempt","ten-TAH","EN","tempt / attempt → tentar. Tenta de novo! = Try again!","Vou tentar chegar mais cedo.","I'll try to arrive earlier."],
["sair","","to leave / to go out","sah-EER","SOM","\"Sigh-EAR\": you SIGH as you LEAVE the party. Saída = exit.","Ele acabou de sair de casa.","He just left home."],
["quanto","","how much / how many","KWAN-too","EN","quantity → quanto. Quanto custa? = How much is it?","Quanto custa essa camiseta?","How much is this T-shirt?"],
["pensar","","to think","pen-SAH (soft r)","EN","pensive → pensar. Penso em você = I think about you.","Preciso pensar antes de decidir.","I need to think before deciding."],
["mal","","badly / poorly / hardly","mow (rhymes with 'cow')","FR","French mal, as in malfunction. Dormi mal = I slept badly. The l sounds like w.","Ele dirige muito mal.","He drives really badly."],
["volta","f","return / turn / lap","VOW-tah","IMG","A VOLT shoots around the circuit and comes back: a full turn. Dar uma volta = take a stroll.","Vamos dar uma volta no parque?","Shall we take a walk in the park?"],
["mundo","m","world","MOON-doo","LA","Latin mundus, as in mundane (worldly). O mundo todo = the whole world.","Ela quer viajar pelo mundo.","She wants to travel the world."],
["menos","","less / fewer / minus","MEH-nooss","EN","minus → menos. Mais ou menos = more or less, so-so.","Hoje está menos frio que ontem.","It's less cold today than yesterday."],
["amigo","m","friend","ah-MEE-goo","ES","Every English speaker knows amigo from Spanish. Feminine: amiga.","Meu amigo vai passar aqui mais tarde.","My friend is going to stop by later."],
["embora","","although / away","eng-BOH-rah","PAD","em + boa hora (at a good hour) shortened. Ir embora = to leave; embora = although.","Já está tarde, vou embora.","It's late already, I'm leaving."],
["problema","m","problem","proh-BLEH-mah","EN","problem → problema, masculine despite the -a. Sem problema = no problem.","Tem um problema com o meu computador.","There's a problem with my computer."],
["carro","m","car","KAH-hoo (rr sounds like h)","EN","car → carro. The double rr is a breathy h: \"KAH-hoo\".","Meu carro está na oficina.","My car is at the mechanic's."],
["lado","m","side","LAH-doo","LA","Latin latus, as in lateral. Do lado = next door. Ao lado de = beside.","Senta aqui do meu lado.","Sit here by my side."],
["novo","","new / young","NOH-voo","LA","Latin novus, as in novel and nova. Ano Novo = New Year.","Comprei um celular novo.","I bought a new cell phone."],
["parte","f","part / share","PAR-chee","EN","part → parte. A maior parte = most of it.","Essa é a melhor parte do filme.","This is the best part of the movie."],
["primeiro","","first","pree-MAY-roo","EN","primary → primeiro. Primeiro andar = first floor.","Hoje é o primeiro dia de aula.","Today is the first day of class."],
["lugar","m","place / seat","loo-GAH (soft r)","LA","Latin locus, as in location. Em primeiro lugar = in the first place.","Esse lugar está ocupado?","Is this seat taken?"],
["voltar","","to come back / to return","vow-TAH","PAD","From volta, the turn: you turn around and come BACK. Já volto = I'll be right back.","A que horas você vai voltar?","What time are you coming back?"],
["dentro","","inside / within","DEN-troo","LA","Latin de intro, as in intro and interior. Dentro de casa = inside the house.","A chave está dentro da gaveta.","The key is inside the drawer."],
["família","f","family","fah-MEE-lyah","EN","family → família. The stress falls on MEE.","Passo o Natal com a minha família.","I spend Christmas with my family."],
["ali","","there (close by)","ah-LEE","NOME","Muhammad Ali stands right THERE, a few steps away: closer than lá.","O banheiro fica ali à direita.","The bathroom is right there on the right."],
["razão","f","reason / being right","hah-ZOWNG (r at the start sounds like h)","EN","reason → razão (-son → -são). Você tem razão = you're right.","Você tem razão, me desculpa.","You're right, I'm sorry."],
["ideia","f","idea","ee-DAY-ah","EN","idea → ideia, just add an i. Boa ideia! = Good idea!","Tive uma ideia ótima!","I had a great idea!"],
["hora","f","hour / time (of day)","OH-rah (h silent)","EN","hour → hora, silent h in both. Que horas são? = What time is it?","Já está na hora de dormir.","It's already time for bed."],
["polícia","f","police","poh-LEE-see-ah","EN","police → polícia. The stress is on LEE. Policial = police officer.","Alguém chamou a polícia?","Did someone call the police?"],
["forma","f","form / shape / way","FOR-mah","EN","form → forma. Em forma = in shape; de forma nenhuma = no way.","Ela vai à academia para ficar em forma.","She goes to the gym to stay in shape."],
["caso","m","case / affair","KAH-zoo","EN","case → caso. Em caso de chuva = in case of rain. Também: um caso = an affair.","Em caso de dúvida, me liga.","In case of doubt, call me."],
["amor","m","love / darling","ah-MOH (soft r)","LA","Latin amor, as in amorous and Cupid's other name. Meu amor = my love.","Ela é o amor da minha vida.","She is the love of my life."],
["pessoa","f","person","peh-SOH-ah","EN","person → pessoa. Always feminine, even for a man: ele é uma pessoa legal.","Ele é uma pessoa muito calma.","He is a very calm person."],
["cabeça","f","head","kah-BEH-sah","LA","Latin caput, as in capital and decapitate. Dor de cabeça = headache.","Estou com dor de cabeça.","I have a headache."],
["pressa","f","hurry / rush","PREH-sah","EN","press → pressa: time is PRESSING. Estou com pressa = I'm in a hurry.","Desculpa, estou com pressa agora.","Sorry, I'm in a hurry right now."],
["ajudar","","to help","ah-zhoo-DAH","LA","Latin adiutare, as in adjutant (an officer's helper). Posso ajudar? = Can I help?","Você pode me ajudar com a mala?","Can you help me with the suitcase?"],
["tarde","f","afternoon / late","TAR-jee","LA","Latin tardus, as in tardy: LATE. As a noun: a tarde, the afternoon. Boa tarde!","Vamos ao parque à tarde.","Let's go to the park in the afternoon."],
["momento","m","moment","moh-MEN-too","EN","moment → momento. Um momento, por favor = One moment, please.","Um momento, já vou te atender.","One moment, I'll be right with you."],
["pronto","","ready / done / there you go","PRON-too","EN","prompt → pronto: ready on the spot. Pronto! also means There, done!","O jantar está pronto!","Dinner is ready!"],
["cidade","f","city / town","see-DAH-jee","PAD","-dade = -ty: city → cidade. Cidade Maravilhosa = Rio's nickname.","São Paulo é uma cidade enorme.","São Paulo is a huge city."],
["encontrar","","to find / to meet","en-kon-TRAH","EN","encounter → encontrar. Vamos nos encontrar? = Shall we meet up?","Não consigo encontrar meus óculos.","I can't find my glasses."],
["frente","f","front","FREN-chee","EN","front → frente. Em frente = straight ahead; na frente de = in front of.","Te espero na frente do cinema.","I'll wait for you in front of the movie theater."],
["passar","","to pass / to spend (time) / to iron","pah-SAH (soft r)","EN","pass → passar. Passar as férias = to spend the holidays. Also passar roupa = to iron clothes.","Vamos passar o fim de semana na praia.","We're going to spend the weekend at the beach."],
["deixar","","to leave (something) / to let","day-SHAH","SOM","\"Day SHAH!\" says the boss: LET the workers go home, LEAVE it for tomorrow. Me deixa! = Leave me alone!","Pode deixar a bolsa aqui.","You can leave your bag here."],
["gente","f","people / we (a gente)","ZHEN-chee","LA","Latin gens, as in gentle and genealogy. A gente = we in everyday speech: a gente vai.","A gente se vê amanhã.","We'll see each other tomorrow."],
["entrar","","to enter / to come in","en-TRAH (soft r)","EN","enter → entrar. Pode entrar! = Come on in!","Pode entrar, a porta está aberta.","Come in, the door is open."],
["chegar","","to arrive / to be enough","sheh-GAH","SOM","\"She GOT here!\" Chegar = to arrive. Chega! = That's enough!","O voo vai chegar às dez.","The flight will arrive at ten."],
["trabalhar","","to work","trah-bah-LYAH","PAD","The verb from trabalho: trabalhar. Trabalho em casa = I work from home.","Hoje não preciso trabalhar.","I don't need to work today."],
["quase","","almost / nearly","KWAH-zee","EN","quasi- → quase: quasi-official, almost official. Quase nunca = hardly ever.","Quase perdi o ônibus.","I almost missed the bus."],
["amanhã","","tomorrow","ah-mah-NYAH (nasal end)","ES","Spanish mañana: the land of tomorrow. Até amanhã! = See you tomorrow!","Amanhã tenho uma entrevista.","Tomorrow I have an interview."],
["história","f","story / history","ees-TOH-ree-ah","EN","history / story → história, silent h. Conta uma história! = Tell a story!","Essa história aconteceu de verdade.","This story really happened."],
["irmão","m","brother","eer-MOWNG (nasal)","ES","Spanish hermano lost the h and nasalized: irmão. Irmã = sister.","Meu irmão mais novo estuda direito.","My younger brother studies law."],
["morrer","","to die","moh-HEH (rr sounds like h)","EN","mortal / mortuary → morrer. Morrer de rir = to die laughing.","Quase morri de rir com essa piada.","I almost died laughing at that joke."],
["maneira","f","way / manner","mah-NAY-rah","EN","manner → maneira. De maneira nenhuma = no way.","Essa é a maneira certa de fazer.","This is the right way to do it."],
["ajuda","f","help","ah-ZHOO-dah","PAD","The noun from ajudar. Preciso de ajuda! = I need help!","Obrigado pela ajuda com a mudança.","Thanks for the help with the move."],
["porta","f","door","POR-tah","EN","portal / porch → porta. Porta-malas = car trunk (door for suitcases).","Fecha a porta, por favor.","Close the door, please."],
["medo","m","fear","MEH-doo","SOM","\"MAY-do\" sounds like \"May doom\": FEAR of what's coming. Ter medo de = to be afraid of.","Tenho medo de altura.","I'm afraid of heights."],
["caminho","m","way / path / road","kah-MEE-nyoo","ES","Spanish camino, as in the Camino de Santiago pilgrimage route. No caminho = on the way.","Passo na padaria no caminho de casa.","I stop at the bakery on the way home."],
["vir","","to come","veer (soft r)","LA","Latin venire, as in venue and convene. Venha! = Come! Vem cá = come here.","Você pode vir à minha festa?","Can you come to my party?"],
["feliz","","happy","feh-LEES","NOME","Felix the Cat always grins: a FELIX is a HAPPY one. Feliz aniversário! = Happy birthday!","Estou muito feliz por você.","I'm very happy for you."],
["ouvir","","to hear / to listen","oh-VEER","FR","French ouïr, as in the courtroom cry \"Oyez!\" (hear ye). Ouvir música = to listen to music.","Gosto de ouvir música no carro.","I like listening to music in the car."],
["matar","","to kill","mah-TAH (soft r)","ES","The matador KILLS the bull. Matar a saudade = to cure your longing by visiting someone.","Esse calor vai me matar!","This heat is going to kill me!"],
["cada","","each / every","KAH-dah","ES","Same in Spanish. Cada um = each one; cada vez mais = more and more.","Cada aluno trouxe um prato.","Each student brought a dish."],
["acontecer","","to happen","ah-kon-teh-SEH","SOM","\"A con-test, eh?\" Something exciting is going to HAPPEN. O que aconteceu? = What happened?","O que vai acontecer agora?","What's going to happen now?"],
["ano","m","year","AH-noo","LA","Latin annus, as in annual and anniversary. Feliz Ano Novo! = Happy New Year!","Ela faz dez anos este ano.","She turns ten this year."],
["rapaz","m","young man / guy","hah-PAHSS (r at the start sounds like h)","SOM","\"Ha, PASS!\" says the young GUY waving off homework. Rapaz! is also a cry of surprise, like Man!","Aquele rapaz trabalha na farmácia.","That young man works at the pharmacy."],
["causa","f","cause / reason","KOW-zah","EN","cause → causa. Por causa de = because of.","Chegamos tarde por causa do trânsito.","We arrived late because of the traffic."],
["filha","f","daughter","FEE-lyah","PAD","filho (son) + a = filha (daughter). nh and lh sound like the ny and ll in canyon and million.","A filha dela já está na faculdade.","Her daughter is already in college."],
["levar","","to take / to carry","leh-VAH (soft r)","EN","lever / elevate → levar: lift it and TAKE it with you. Levar o cachorro = take the dog.","Não esquece de levar o guarda-chuva.","Don't forget to take the umbrella."],
["conta","f","bill / account","KON-tah","EN","count / account → conta. A conta, por favor = The check, please.","Garçom, a conta, por favor!","Waiter, the check, please!"],
["arma","f","weapon / gun","AR-mah","FALSO","Not your arm (that's braço)! It's armament: a weapon. Arma de fogo = firearm.","O policial guardou a arma.","The police officer put away the gun."],
["pessoal","","personal / folks (informal)","peh-soh-OW","PAD","pessoa (person) + -al = personal. Brazilians greet a group with Oi, pessoal! = Hi, everyone!","Oi, pessoal, tudo bem?","Hi, everyone, how's it going?"],
["quarto","m","bedroom / room / quarter","KWAR-too","IMG","A QUARTER of the house is your BEDROOM. Also means fourth and a quarter.","Meu quarto fica no segundo andar.","My bedroom is on the second floor."],
["adeus","","farewell / goodbye (final)","ah-DEH-oos","FR","a Deus = to God, like French adieu: a heavy goodbye. For everyday leaving, use tchau.","Ela disse adeus e entrou no trem.","She said goodbye and boarded the train."],
["cara","m","guy / dude (as a noun: face, f)","KAH-rah","FALSO","Not \"dear\" (that's querido)! O cara = the guy, Brazil's version of dude. A cara = the face.","Esse cara é muito engraçado.","This guy is really funny."],
["juntos","","together","ZHOON-toos","EN","joint / junction → juntos: joined together. Feminine: juntas.","Vamos estudar juntos hoje?","Shall we study together today?"],
["difícil","","difficult / hard","jee-FEE-seew","EN","difficult → difícil. Stress on FEE.","Essa prova foi muito difícil.","That test was very hard."],
["manhã","f","morning","mah-NYAH (nasal end)","ES","Spanish mañana means both tomorrow and morning; Portuguese splits them: amanhã / manhã. Bom dia covers the greeting.","Corro todos os dias de manhã.","I run every morning."],
["importante","","important","eem-por-TAN-chee","EN","important → importante, add -e. O mais importante = the most important thing.","Tenho uma reunião importante amanhã.","I have an important meeting tomorrow."],
["poder","","can / to be able to / power","poh-DEH (soft r)","EN","potent / power → poder. Posso? = May I? Also a noun: o poder = the power.","Você vai poder vir amanhã?","Will you be able to come tomorrow?"],
["água","f","water","AH-gwah","LA","Latin aqua, as in aquarium. Água de coco = coconut water.","Me dá um copo de água?","Can you give me a glass of water?"],
["começar","","to begin / to start","koh-meh-SAH","FR","French commencer, as in commencement. O filme vai começar!","A aula vai começar em cinco minutos.","Class is going to start in five minutes."],
["perto","","near / close","PEHR-too","SOM","\"PEHR-to\" like \"pert\": a pert little shop right NEAR here. Perto de = close to.","Tem um mercado perto daqui?","Is there a supermarket near here?"],
["semana","f","week","seh-MAH-nah","ES","Spanish semana, from Latin septimana (seven days). Fim de semana = weekend.","Vejo você na semana que vem.","I'll see you next week."],
["usar","","to use / to wear","oo-ZAH (soft r)","EN","use → usar. Also wear: usar óculos = wear glasses.","Posso usar o seu carregador?","Can I use your charger?"],
["corpo","m","body","KOR-poo","EN","corpse / corporal → corpo. Living bodies too: corpo humano.","O corpo precisa de descanso.","The body needs rest."],
["chefe","m","boss / chief","SHEH-fee","EN","chef / chief → chefe. Not only in kitchens: meu chefe = my boss.","Meu chefe me deu o dia de folga.","My boss gave me the day off."],
["jogo","m","game / match","ZHOH-goo","EN","jog / joke → jogo: playful fun. Jogo de futebol = soccer match.","Você vai ver o jogo hoje?","Are you going to watch the game today?"],
["fala","f","speech / line / way of talking","FAH-lah","PAD","The noun of falar: what you say. Fala sério! = Get real! Uma fala = a line in a play.","Ele esqueceu a fala dele na peça.","He forgot his line in the play."],
["moça","f","young woman / miss","MOH-sah","SOM","\"MOSS-a\" sounds like moss on a lovely old garden where a YOUNG WOMAN reads. Moça! = Miss! to call a waitress.","Moça, pode trazer o cardápio?","Miss, could you bring the menu?"],
["realmente","","really / truly","heh-ow-MEN-chee","PAD","-mente = -ly: real → really. The r at the start sounds like h.","Eu realmente gostei do presente.","I really liked the gift."],
["terra","f","earth / land / ground","TEH-hah (rr sounds like h)","LA","Latin terra, as in terrain and territory. A Terra = planet Earth.","As crianças estão brincando na terra.","The kids are playing in the dirt."],
["ontem","","yesterday","ON-teng (nasal end)","SOM","\"ON-tame\": ONce tame, back YESTERDAY. Ontem à noite = last night.","Ontem choveu o dia inteiro.","Yesterday it rained all day."],
["comer","","to eat","koh-MEH (soft r)","ES","Spanish comer, same. Vamos comer? = Let's eat? Comida = food.","O que você quer comer hoje?","What do you want to eat today?"],
["dormir","","to sleep","dor-MEER","EN","dormitory / dormant → dormir. Durma bem! = Sleep well!","Preciso dormir cedo hoje.","I need to sleep early tonight."],
["escola","f","school","es-KOH-lah","EN","school / scholar → escola, with an e in front as Portuguese loves. Escola de samba!","Meu filho vai a pé para a escola.","My son walks to school."],
["logo","","soon / right away / therefore","LOH-goo","FALSO","Not a brand logo! Até logo = see you soon. Penso, logo existo = I think, therefore I am.","Volto logo, me espera.","I'll be back soon, wait for me."],
["querido","","dear / beloved","keh-REE-doo","PAD","From querer, to want or love: wanted = beloved. Querido amigo = dear friend.","Querido, você viu minhas chaves?","Honey, have you seen my keys?"],
["fim","m","end","fing (nasal)","FR","French fin, at the end of old films. Fim de semana = weekend (end of week).","Gostei muito do fim do livro.","I really liked the end of the book."],
["agente","m","agent","ah-ZHEN-chee","FALSO","agent → agente. Careful: written together it's an agent; a gente (two words) means we.","O agente de viagens reservou o hotel.","The travel agent booked the hotel."],
["equipe","f","team / staff","eh-KEE-pee","FR","French équipe, as in equipped: a team kitted out together. Brazil says equipe; Portugal says equipa.","Nossa equipe ganhou o campeonato.","Our team won the championship."],
["colega","m","colleague / classmate","koh-LEH-gah","EN","colleague → colega. Works for coworkers and classmates; a colega for a woman.","Meu colega de trabalho faz aniversário hoje.","My coworker has a birthday today."],
["marido","m","husband","mah-REE-doo","EN","married → marido: the MARRIED man. Feminine pair: esposa or mulher.","Meu marido cozinha melhor que eu.","My husband cooks better than I do."],
["coração","m","heart","koh-rah-SOWNG (nasal)","EN","core / courage → coração: the core of you. -ção is said \"sowng\".","Ela tem um coração de ouro.","She has a heart of gold."],
["viver","","to live / to be alive","vee-VEH (soft r)","EN","vivid / survive → viver. Viver bem = to live well. For where you live, prefer morar.","Quero viver muitos anos.","I want to live for many years."],
["parar","","to stop","pah-RAH","SOM","\"Pa-RAH!\" a traffic cop's whistle: STOP! Pare is on every Brazilian stop sign.","O ônibus vai parar aqui.","The bus is going to stop here."],
["segundo","","second","seh-GOON-doo","EN","second → segundo. Both an order (segundo lugar) and a slice of a minute.","Ele ficou em segundo lugar na corrida.","He came in second in the race."],
["mão","f","hand","mowng (nasal)","LA","Latin manus, as in manual and manicure. Feminine despite -o: a mão.","Me dá a sua mão.","Give me your hand."],
["baixo","","low / short (height) / quiet","BUY-shoo","IT","Italian basso, a LOW singing voice. Fala baixo = speak quietly. Embaixo = below.","Meu irmão é mais baixo que eu.","My brother is shorter than me."],
["maior","","bigger / biggest / major","mah-YOR","EN","major → maior. Maior de idade = of legal age.","Esse é o maior shopping da cidade.","This is the biggest mall in the city."],
["meio","","half / middle / kind of","MAY-oo","IMG","A line down the MIDDLE splits it in half. Meio-dia = noon. Meio cansado = kind of tired.","Estou meio cansado hoje.","I'm kind of tired today."],
["mau","","bad / evil","mow (rhymes with 'cow')","LA","Latin malus, as in malware. Sounds the same as mal (badly); mau is the adjective: um mau dia.","Ele não é um mau menino.","He's not a bad boy."],
["andar","","to walk / floor (of a building)","an-DAH (soft r)","IT","Andante in music = a WALKING pace. As a noun: o terceiro andar = the third floor.","Gosto de andar na praia de manhã.","I like walking on the beach in the morning."],
["rápido","","fast / quick","HAH-pee-doo","EN","rapid → rápido. Stress on the first syllable.","Esse trem é muito rápido.","This train is very fast."],
["número","m","number","NOO-meh-roo","EN","number / numeral → número. Qual é o seu número? = What's your number?","Me passa o seu número de telefone.","Give me your phone number."],
["festa","f","party","FES-tah","EN","festival / fiesta → festa. Festa Junina = the June harvest party.","Vai ter festa na casa do Pedro.","There's going to be a party at Pedro's house."],
["buscar","","to fetch / to pick up / to seek","boos-KAH","ES","Spanish buscar. Vou te buscar = I'll pick you up.","Vou buscar as crianças na escola.","I'm going to pick up the kids from school."],
["perder","","to lose / to miss","pehr-DEH (soft r)","EN","perdition → perder. Perder o ônibus = miss the bus.","Não quero perder o voo.","I don't want to miss the flight."],
["esperar","","to wait / to hope / to expect","es-peh-RAH","ES","Spanish esperar, from Latin sperare, as in desperate (without hope). Espera aí! = Hang on!","Pode esperar um minuto?","Can you wait a minute?"],
["irmã","f","sister","eer-MAH (nasal end)","PAD","irmão minus the o: irmã. The tilde makes the final a nasal.","Minha irmã mora em Lisboa.","My sister lives in Lisbon."],
["possível","","possible","poh-SEE-vew","EN","possible → possível: -ble becomes -vel. Se possível = if possible.","É possível mudar a data?","Is it possible to change the date?"],
["contra","","against","KON-trah","EN","contra-, as in contradict and contraband. Contra a parede = against the wall.","Sou contra essa ideia.","I'm against that idea."],
["acabar","","to finish / to end","ah-kah-BAH","SOM","\"A KABOOM!\" and it's all OVER. Acabei de chegar = I just arrived.","Acabei de chegar em casa.","I just got home."],
["contar","","to count / to tell","kon-TAH (soft r)","EN","count / recount → contar: to count numbers or recount a story. Conta! = Tell me!","Vou te contar uma novidade.","I'm going to tell you some news."],
["olhar","","to look / to watch","oh-LYAH","SOM","\"Oh, LYAH!\" you gasp as you LOOK. Olha! = Look!","Olha só que lindo esse lugar!","Just look how beautiful this place is!"],
["pena","f","pity / shame / feather","PEH-nah","FALSO","Not a pen (that's caneta)! Que pena! = What a shame! Vale a pena = it's worth it. Old quills were feathers.","Vale a pena visitar o museu.","It's worth visiting the museum."],
["longe","","far / far away","LON-zhee","EN","long → longe: a long way off. Longe daqui = far from here.","O aeroporto fica longe do centro.","The airport is far from downtown."],
["pedir","","to ask for / to order","peh-JEER","LA","Latin petere, as in petition. Pedir uma pizza = to order a pizza.","Vamos pedir uma pizza hoje?","Shall we order a pizza tonight?"],
["estranho","","strange / weird / stranger","es-TRAH-nyoo","EN","strange / stranger → estranho. nh = ny, like canyon.","Ouvi um barulho estranho lá fora.","I heard a strange noise outside."],
["fácil","","easy","FAH-seew","EN","facile / facility → fácil. Final l sounds like w.","A receita é muito fácil.","The recipe is very easy."],
["brincar","","to play (games) / to joke","breen-KAH","IMG","Kids at the BRINK of a pool, splashing and playing. Tô brincando = I'm just kidding.","As crianças adoram brincar no parque.","The kids love playing in the park."],
["bebê","m","baby","beh-BEH","FR","French bébé, same sound. Brazil writes bebê; Portugal bebé.","O bebê está dormindo no quarto.","The baby is sleeping in the bedroom."],
["plano","m","plan","PLAH-noo","EN","plan → plano. Plano de saúde = health insurance plan.","Qual é o plano para sábado?","What's the plan for Saturday?"],
["velho","","old","VEH-lyoo","IMG","A VELvet armchair, worn and OLD. Meu velho = my old man (dad).","Esse sofá é muito velho.","This sofa is very old."],
["conseguir","","to manage / to be able / to get","kon-seh-GHEER","EN","consequence / get → conseguir: you GET there in the end. Consegui! = I did it!","Consegui um emprego novo!","I got a new job!"],
["passado","m","past","pah-SAH-doo","EN","passed → passado: what has passed. Semana passada = last week.","Não quero falar do passado.","I don't want to talk about the past."],
["tomar","","to take / to drink","toh-MAH (soft r)","SOM","A TOMATO juice: you TAKE a sip and DRINK. Tomar banho = take a shower.","Vou tomar um banho rápido.","I'm going to take a quick shower."],
["jantar","m","dinner / to have dinner","zhan-TAH (soft r)","SOM","\"Jaunty\" mood after a good DINNER. Both noun and verb: vamos jantar?","O jantar está na mesa.","Dinner is on the table."],
["depressa","","quickly / fast","deh-PREH-sah","PAD","de + pressa (hurry): in a hurry. Anda depressa! = Walk faster!","Vem depressa, o filme já começou!","Come quickly, the movie already started!"],
["pergunta","f","question","pehr-GOON-tah","SOM","\"Pear GOON\" asking a QUESTION with a puzzled face. Fazer uma pergunta = ask a question.","Posso fazer uma pergunta?","Can I ask a question?"],
["tirar","","to take off / to take out","chee-RAH","SOM","\"Tear-AH\": you TEAR it off. Tirar uma foto = take a picture.","Pode tirar uma foto nossa?","Can you take a picture of us?"],
["pequeno","","small / little","peh-KEH-noo","ES","Spanish pequeño. Feminine pequena. Pequeno-almoço is breakfast only in Portugal.","Moro num apartamento pequeno.","I live in a small apartment."],
["descobrir","","to discover / to find out","jees-koh-BREER","EN","discover → descobrir: un-cover. Descobri que = I found out that.","Descobri um café ótimo perto daqui.","I discovered a great café near here."],
["sala","f","living room / room / classroom","SAH-lah","IT","Italian sala, as in salon. Sala de aula = classroom; sala de estar = living room.","Vamos ver TV na sala.","Let's watch TV in the living room."],
["telefone","m","telephone","teh-leh-FOH-nee","EN","telephone → telefone, ph becomes f. Usually the landline; cell phone is celular.","O telefone tocou de madrugada.","The phone rang in the middle of the night."],
["errado","","wrong / mistaken","eh-HAH-doo (rr sounds like h)","EN","err / error → errado. Número errado = wrong number.","Acho que você pegou o ônibus errado.","I think you took the wrong bus."],
["vivo","","alive / lively / bright","VEE-voo","EN","vivid / vivacious → vivo. Ao vivo = live (broadcast).","O show vai passar ao vivo.","The concert will be broadcast live."],
["menina","f","girl","meh-NEE-nah","SOM","\"Many NEE-na\" dolls: a GIRL's collection. Masculine: menino.","A menina está aprendendo a ler.","The girl is learning to read."],
["correr","","to run","koh-HEH (rr sounds like h)","EN","current / courier → correr: things that run. Correr risco = run a risk.","Eu gosto de correr no parque.","I like running in the park."],
["mudar","","to change / to move (house)","moo-DAH (soft r)","EN","mutate → mudar. Mudar de casa = move house.","Vamos mudar de apartamento em março.","We're moving apartments in March."],
["sentir","","to feel","sen-CHEER","EN","sense / sentiment → sentir. Sinto muito = I'm very sorry.","Estou começando a sentir frio.","I'm starting to feel cold."],
["cama","f","bed","KAH-mah","SOM","\"Karma\" without the r: good KARMA, good BED. Ir para a cama = go to bed.","Ainda estou na cama.","I'm still in bed."],
["comida","f","food","koh-MEE-dah","ES","Spanish comida, from comer (eat). Comida caseira = home cooking.","A comida baiana é deliciosa.","Bahian food is delicious."],
["bastante","","quite / a lot / enough","bahs-TAN-chee","IT","Italian basta! = enough! Bastante = plenty, quite a lot.","Ela fala inglês bastante bem.","She speaks English quite well."],
["provavelmente","","probably","proh-vah-vew-MEN-chee","PAD","provável (probable) + -mente (-ly) = probably.","Provavelmente vou chegar às oito.","I'll probably arrive at eight."],
["palavra","f","word","pah-LAH-vrah","EN","parable → palavra: both come from Greek parabole. Dou minha palavra = I give my word.","Não entendi essa palavra.","I didn't understand that word."],
["diferente","","different","jee-feh-REN-chee","EN","different → diferente, one f and an extra e.","Cada cidade tem um sotaque diferente.","Each city has a different accent."],
["voz","f","voice","voss","LA","Latin vox, as in vocal and vox pop. Em voz alta = out loud.","Ela tem uma voz linda.","She has a beautiful voice."],
["demais","","too much / too / really (slang)","jee-MICE","PAD","de + mais (more): more than enough. Slang: Esse show foi demais! = That show was awesome!","Comi demais no almoço.","I ate too much at lunch."],
["pagar","","to pay","pah-GAH (soft r)","EN","pay → pagar: same p-a start. Pagar a conta = pay the bill.","Posso pagar com cartão?","Can I pay by card?"],
["médico","m","doctor (physician)","MEH-jee-koo","EN","medic / medical → médico. Feminine: médica.","Preciso marcar uma consulta com o médico.","I need to make an appointment with the doctor."],
["seguir","","to follow / to keep going","seh-GHEER","EN","sequel / sequence → seguir: what follows. Siga em frente = keep going straight.","Você pode seguir essa rua até o final.","You can follow this street to the end."],
["sangue","m","blood","SAN-ghee","FR","French sang, as in sanguine. Doar sangue = to donate blood.","Ele não gosta de ver sangue.","He doesn't like seeing blood."],
["único","","only / unique","OO-nee-koo","EN","unique → único. Filho único = only child.","Ela é filha única.","She is an only child."],
["acreditar","","to believe","ah-kreh-jee-TAH","EN","credit / credible → acreditar: to give credit. Não acredito! = I can't believe it!","Não consigo acreditar nisso!","I can't believe this!"],
["local","m","place / site / local","loh-KOW","EN","local → local, as a noun too: o local da festa = the party venue.","Qual é o local da reunião?","Where is the meeting being held?"],
["próprio","","own / proper / oneself","PROH-pree-oo","EN","proper / property → próprio. Meu próprio carro = my own car.","Ela quer abrir o próprio negócio.","She wants to open her own business."],
["país","m","country (nation)","pah-EES","FR","French pays, as in peasant (a country person). Two syllables: pa-ÍS.","O Brasil é um país enorme.","Brazil is a huge country."],
["forte","","strong","FOR-chee","EN","fort / fortitude → forte. Café forte = strong coffee.","Esse café está muito forte.","This coffee is very strong."],
["partir","","to leave / to depart / to break","par-CHEER","EN","depart → partir. A partir de hoje = starting today.","O trem vai partir às seis.","The train will depart at six."],
["especial","","special","es-peh-see-OW","EN","special → especial, with an extra e at the front.","Hoje é um dia especial.","Today is a special day."],
["livro","m","book","LEE-vroo","FR","French livre and Spanish libro, from Latin liber, as in library. Livraria = bookstore (false friend!).","Estou lendo um livro ótimo.","I'm reading a great book."],
["continuar","","to continue / to keep on","kon-chee-noo-AH","EN","continue → continuar. Continua! = Keep going!","Vamos continuar amanhã.","Let's continue tomorrow."],
["resto","m","rest / remainder","HES-too","EN","rest → resto: what's left. O resto do dia = the rest of the day.","Guardei o resto da pizza.","I saved the rest of the pizza."],
["ar","m","air","ar (soft r)","LA","Latin aer, as in aerial. Ar-condicionado = air conditioning.","Abre a janela para entrar ar.","Open the window to let some air in."],
["hospital","m","hospital","os-pee-TOW (h silent)","EN","hospital → hospital, silent h, final l sounds like w.","Ela trabalha no hospital à noite.","She works at the hospital at night."],
["sítio","m","small farm / country place","SEE-chee-oo","FALSO","Not a website (that's site)! In Brazil, um sítio is a small country farm where families spend weekends.","Passamos o feriado no sítio do meu tio.","We spent the holiday at my uncle's farm."],
["ligar","","to call / to turn on / to connect","lee-GAH","EN","ligament → ligar: it ties things together. Te ligo = I'll call you; ligar a TV = turn on the TV.","Me liga quando chegar.","Call me when you get there."],
["minuto","m","minute","mee-NOO-too","EN","minute → minuto. Só um minuto! = Just a minute!","Espera um minuto, já volto.","Wait a minute, I'll be right back."],
["sentido","m","sense / meaning / direction","sen-CHEE-doo","EN","sense → sentido. Faz sentido = makes sense; sentido único = one-way.","Isso não faz sentido nenhum.","That makes no sense at all."],
["direito","m","right (legal) / law / straight","jee-RAY-too","EN","direct / right → direito. Faculdade de direito = law school. Lado direito = right side.","Ela estuda direito na faculdade.","She studies law at university."],
["café","m","coffee / café","kah-FEH","EN","coffee / café → café. Café da manhã = breakfast (morning coffee).","Quer tomar um café comigo?","Do you want to have a coffee with me?"],
["criança","f","child / kid","kree-AN-sah","EN","create / creature → criança: a little creation. Always feminine: a criança.","A criança está brincando no quintal.","The child is playing in the backyard."],
["luz","f","light","looss","LA","Latin lux, as in lucid and lux. Conta de luz = electricity bill.","Apaga a luz, por favor.","Turn off the light, please."],
["filme","m","movie / film","FEEW-mee","EN","film → filme, add -e. Filme de terror = horror movie.","Vamos ver um filme hoje à noite?","Shall we watch a movie tonight?"],
["música","f","music / song","MOO-zee-kah","EN","music → música. Stress on MOO. Also means a single song.","Essa música me lembra a praia.","This song reminds me of the beach."],
["pôr","","to put / to place","por (soft r)","EN","posit / deposit → pôr. The hat (^) separates it from the preposition por. Pôr do sol = sunset.","Pode pôr o prato na mesa.","You can put the plate on the table."],
["querer","","to want / to love","keh-REH (soft r)","LA","Latin quaerere (to seek), as in query: what are you seeking? Quero = I want.","O que você vai querer de sobremesa?","What would you like for dessert?"],
["fogo","m","fire","FOH-goo","LA","Latin focus, the fireplace at the center of a home. Fogos = fireworks.","Cuidado com o fogo da churrasqueira.","Careful with the barbecue fire."],
["beber","","to drink","beh-BEH (soft r)","EN","beverage → beber. Bebida = drink.","Você quer beber alguma coisa?","Would you like something to drink?"],
["ganhar","","to win / to earn / to get","gah-NYAH","EN","gain → ganhar. Ganhar presente = get a gift.","Quem vai ganhar o jogo hoje?","Who's going to win the game today?"],
["ponto","m","point / dot / stop (bus)","PON-too","EN","point → ponto. Ponto de ônibus = bus stop.","Te espero no ponto de ônibus.","I'll wait for you at the bus stop."],
["manter","","to keep / to maintain","man-TEH","EN","maintain → manter, from mão (hand) + ter (hold): hold in hand.","Tente manter a calma.","Try to keep calm."],
["precisar","","to need","preh-see-ZAH","EN","precise → precisar: what you need precisely. Preciso de = I need.","Você precisa de alguma coisa?","Do you need anything?"],
["rua","f","street","HOO-ah (r at the start sounds like h)","FR","French rue, as in Paris street signs. Na rua = in the street, outside.","Moro na rua da padaria.","I live on the street with the bakery."],
["pé","m","foot","peh","EN","pedal / pedestrian → pé. A pé = on foot.","Vou a pé para o trabalho.","I walk to work."],
["último","","last / latest","OOW-chee-moo","EN","ultimate → último. A última vez = the last time.","Esse é o último ônibus da noite.","This is the last bus of the night."],
["pele","f","skin","PEH-lee","EN","peel → pele: the skin you peel off fruit. Pelé the footballer is a different word!","O sol queimou minha pele.","The sun burned my skin."],
["cedo","","early","SEH-doo","SOM","\"SAY-do\": SAY \"do it EARLY\". Acordar cedo = wake up early.","Amanhã preciso acordar cedo.","Tomorrow I need to wake up early."],
["boca","f","mouth","BOH-kah","IT","Italian bocca, as in a big open mouth at the Bocca della Verità. Boca de urna = exit poll.","Não fala de boca cheia!","Don't talk with your mouth full!"],
["jovem","","young / young person","ZHOH-veng (nasal end)","EN","juvenile → jovem. Os jovens = young people.","Ele é jovem demais para dirigir.","He's too young to drive."],
["comprar","","to buy","kom-PRAH","EN","comprador / compare prices → comprar. Fazer compras = go shopping.","Vou comprar pão na padaria.","I'm going to buy bread at the bakery."],
["situação","f","situation","see-too-ah-SOWNG","PAD","-tion → -ção: situation → situação.","A situação está sob controle.","The situation is under control."],
["esposa","f","wife","es-POH-zah","EN","spouse → esposa. Masculine: esposo, though marido is more common.","A esposa dele é arquiteta.","His wife is an architect."],
["jogar","","to play (games, sports) / to throw","zhoh-GAH","PAD","The verb of jogo: jogar futebol = play soccer. Jogar fora = throw away.","Vamos jogar futebol no sábado?","Shall we play soccer on Saturday?"],
["amiga","f","friend (female)","ah-MEE-gah","PAD","amigo with -a: a female friend. Minha melhor amiga = my best friend.","Vou viajar com uma amiga.","I'm traveling with a friend."],
["seguro","","safe / sure / insurance","seh-GOO-roo","EN","secure → seguro. As a noun, seguro do carro = car insurance.","Esse bairro é seguro à noite?","Is this neighborhood safe at night?"],
["questão","f","question / issue / matter","kes-TOWNG","PAD","-tion → -tão: question → questão. Faço questão = I insist.","É uma questão de tempo.","It's a matter of time."],
["encontro","m","meeting / date","en-KON-troo","EN","encounter → encontro. Primeiro encontro = first date.","Hoje tenho um encontro com ela.","Today I have a date with her."],
["cão","m","dog","kowng (nasal)","LA","Latin canis, as in canine. In Brazil, cachorro is the everyday word; cão sounds literary.","Cão que ladra não morde.","A barking dog doesn't bite."],
["negócio","m","business / deal / thing","neh-GOH-see-oo","EN","negotiate → negócio. Fechar negócio = close a deal.","Ele abriu um negócio de comida.","He opened a food business."],
["alegre","","cheerful / happy","ah-LEH-gree","IT","Italian allegro, a lively tempo in music. Porto Alegre = Happy Port.","Ela é uma pessoa muito alegre.","She is a very cheerful person."],
["mensagem","f","message","men-SAH-zheng","EN","message → mensagem. -age turns into -agem.","Te mandei uma mensagem agora.","I just sent you a message."],
["próximo","","next / close","PROH-see-moo (x like ss)","EN","proximity → próximo. Próxima semana = next week.","Desço no próximo ponto.","I'm getting off at the next stop."],
["banho","m","bath / shower","BAH-nyoo","IT","Italian bagno. Tomar banho = to shower; banheiro = bathroom.","Vou tomar banho antes do jantar.","I'm going to shower before dinner."],
["chamada","f","call / roll call","shah-MAH-dah","PAD","From chamar (to call): a call. Fazer a chamada = take attendance.","Perdi uma chamada da minha mãe.","I missed a call from my mom."],
["novamente","","again","noh-vah-MEN-chee","PAD","nova (new) + -mente: anew. Same as de novo, a little more formal.","Por favor, tente novamente mais tarde.","Please try again later."],
["futuro","m","future","foo-TOO-roo","EN","future → futuro. No futuro = in the future.","Ninguém sabe o futuro.","Nobody knows the future."],
["perguntar","","to ask (a question)","pehr-goon-TAH","PAD","The verb of pergunta. To ask FOR something is pedir; to ask a question is perguntar.","Posso te perguntar uma coisa?","Can I ask you something?"],
["notícia","f","news (item)","noh-CHEE-see-ah","EN","notice → notícia. As notícias = the news. Boa notícia! = Good news!","Tenho uma notícia boa para você.","I have some good news for you."],
["chamar","","to call / to name","shah-MAH (soft r)","FR","French clamer / English claim: call out loud. Como você se chama? = What's your name?","Como se chama esse prato?","What's this dish called?"],
["cabelo","m","hair (on the head)","kah-BEH-loo","LA","Latin capillus, as in capillary (hair-thin). Cortar o cabelo = get a haircut.","Vou cortar o cabelo amanhã.","I'm getting a haircut tomorrow."],
["grupo","m","group","GROO-poo","EN","group → grupo. Grupo do WhatsApp = the inevitable family chat.","Ela estuda em grupo com os colegas.","She studies in a group with her classmates."],
["doutor","m","doctor (title) / sir","doh-TOH (soft r)","EN","doctor → doutor. Brazilians also use it as a respectful title for lawyers and bosses.","O doutor já vai te atender.","The doctor will see you shortly."],
["livre","","free (not busy) / available","LEE-vree","EN","liberty → livre. Free of charge is grátis. Tempo livre = free time.","Você está livre no sábado?","Are you free on Saturday?"],
["viagem","f","trip / journey","vee-AH-zheng","EN","voyage → viagem. Boa viagem! = Have a good trip!","Como foi a viagem?","How was the trip?"],
["conversa","f","conversation / chat","kon-VEHR-sah","EN","conversation → conversa, just chop the end. Conversa fiada = small talk, nonsense.","Tivemos uma conversa longa ontem.","We had a long conversation yesterday."],
["fugir","","to flee / to run away / to escape","foo-ZHEER","EN","fugitive → fugir. O cachorro fugiu = the dog ran away.","O gato tentou fugir pela janela.","The cat tried to escape through the window."],
["lista","f","list","LEES-tah","EN","list → lista. Lista de compras = shopping list.","Fiz uma lista de compras.","I made a shopping list."],
["escritório","m","office","es-kree-TOH-ree-oo","PAD","From escrever (to write): the place where you write. Also a law firm: escritório de advocacia.","Meu escritório fica no centro.","My office is downtown."],
["final","m","end / final","fee-NOW","EN","final → final. No final = in the end. Final de semana = weekend.","Gostei do final do filme.","I liked the ending of the movie."],
["alto","","tall / high / loud","OW-too","IT","Italian alto, the HIGH voice in a choir. Fala mais alto = speak louder.","Meu pai é muito alto.","My dad is very tall."],
["bonito","","pretty / handsome / nice","boh-NEE-too","ES","Spanish bonito, same word. Feminine: bonita. Que dia bonito!","Que vestido bonito!","What a pretty dress!"],
["chão","m","floor / ground","showng (nasal)","SOM","\"SHOWN\" on the FLOOR: everything you drop is shown down there. Rhymes with não.","O livro caiu no chão.","The book fell on the floor."],
["campo","m","field / countryside","KAM-poo","EN","camp / campus → campo. Campo de futebol = soccer field.","Eles moram no campo, longe da cidade.","They live in the countryside, far from the city."],
["perfeito","","perfect","pehr-FAY-too","EN","perfect → perfeito: -ct becomes -it. Perfeito! = Perfect!","O dia estava perfeito para praia.","The day was perfect for the beach."],
["tio","m","uncle","CHEE-oo","ES","Spanish tío. Kids call any grown-up man tio. Tia = aunt.","Meu tio mora no Rio.","My uncle lives in Rio."],
["completamente","","completely","kom-pleh-tah-MEN-chee","PAD","completa + -mente = completely. -mente = -ly.","Esqueci completamente da reunião.","I completely forgot about the meeting."],
["breve","","brief / short / soon","BREH-vee","EN","brief / brevity → breve. Em breve = soon.","O filme chega em breve aos cinemas.","The movie is coming to theaters soon."],
["remédio","m","medicine / remedy","heh-MEH-jee-oo","EN","remedy → remédio. Tomar remédio = take medicine. Farmácia sells them.","Não esquece de tomar o remédio.","Don't forget to take your medicine."],
["normal","","normal","nor-MOW","EN","normal → normal, but the final l sounds like w.","É normal sentir um pouco de medo.","It's normal to feel a bit afraid."],
["mesa","f","table","MEH-zah","IMG","A MESA in the desert is a flat-topped mountain: a giant TABLE. Pôr a mesa = set the table.","O jantar está na mesa!","Dinner's on the table!"],
["simples","","simple","SEEM-pleess","EN","simple → simples, with a final s even in the singular.","A receita é bem simples.","The recipe is really simple."],
["projeto","m","project / plan","proh-ZHEH-too","EN","project → projeto: -ject becomes -jeto.","Estou trabalhando num projeto novo.","I'm working on a new project."],
["emprego","m","job / employment","em-PREH-goo","EN","employ → emprego. Procurar emprego = look for a job.","Ela conseguiu um emprego novo.","She got a new job."],
["linha","f","line","LEE-nyah","EN","line → linha. Linha do metrô = subway line; linha de costura = thread.","Qual linha de metrô vai para o centro?","Which subway line goes downtown?"],
["real","","real / royal / Brazilian currency","heh-OW","EN","real → real, and royal too. O real is Brazil's money: dez reais.","Essa história é real?","Is this story real?"],
["assunto","m","subject / topic / matter","ah-SOON-too","SOM","\"A soon-to\" be TOPIC of gossip. Mudar de assunto = change the subject.","Vamos mudar de assunto?","Shall we change the subject?"],
["ordem","f","order","OR-deng (nasal end)","EN","order → ordem. Em ordem = in order; tudo em ordem = everything's fine.","Coloque os livros em ordem.","Put the books in order."],
["fundo","m","bottom / back / background / fund","FOON-doo","EN","fund / fundamental → fundo: the base. No fundo = at the back, deep down.","Sentei no fundo do ônibus.","I sat at the back of the bus."],
["acidente","m","accident","ah-see-DEN-chee","EN","accident → acidente, one c less and an -e.","Houve um acidente na estrada.","There was an accident on the highway."],
["modo","m","way / mode / manner","MOH-doo","EN","mode → modo. De modo geral = generally.","Gosto do seu modo de falar.","I like your way of speaking."],
["resposta","f","answer / reply","hes-POS-tah","EN","response → resposta. Responder = to answer.","Ainda estou esperando a resposta dele.","I'm still waiting for his answer."],
["mamãe","f","mom / mommy","mah-MAING (nasal end)","EN","mama → mamãe, ending in a nasal hum. Papai = daddy.","Mamãe, posso brincar lá fora?","Mommy, can I play outside?"],
["avião","m","airplane","ah-vee-OWNG (nasal)","EN","aviation → avião. De avião = by plane.","O avião já está pousando.","The plane is already landing."],
["erro","m","mistake / error","EH-hoo (rr sounds like h)","EN","error → erro. Cometer um erro = make a mistake.","Achei um erro no seu texto.","I found a mistake in your text."],
["verdadeiro","","true / real / genuine","vehr-dah-DAY-roo","PAD","verdade (truth) + -eiro: full of truth. Um amigo verdadeiro = a true friend.","Ele é um amigo verdadeiro.","He's a true friend."],
["idade","f","age","ee-DAH-jee","PAD","-dade = -ty, but here age hides inside: idade. Qual é a sua idade? = How old are you?","Com que idade você aprendeu a nadar?","At what age did you learn to swim?"],
["fantástico","","fantastic","fan-TAHS-chee-koo","EN","fantastic → fantástico. Also the name of Brazil's famous Sunday-night TV show.","Foi um show fantástico!","It was a fantastic concert!"],
["espaço","m","space / room","es-PAH-soo","EN","space → espaço, with Portugal's favorite extra e in front.","Não tem espaço no carro para a mala.","There's no room in the car for the suitcase."],
["serviço","m","service / work / job","sehr-VEE-soo","EN","service → serviço. Área de serviço = laundry area of an apartment.","O serviço desse restaurante é ótimo.","The service at this restaurant is great."],
["ler","","to read","leh (soft r)","LA","Latin legere, as in legible and lecture. Leio, lê, lemos: short and sweet.","Gosto de ler antes de dormir.","I like to read before bed."],
["louco","","crazy / mad","LOH-koo","ES","Spanish loco, everyone's word for crazy. Louco por = crazy about.","Esse trânsito vai me deixar louco.","This traffic is going to drive me crazy."],
["conhecer","","to know (a person or place) / to meet","koh-nyeh-SEH","EN","cognition / recognize → conhecer. Prazer em te conhecer = nice to meet you.","Quero conhecer a Bahia um dia.","I want to visit Bahia one day."],
["lindo","","beautiful / lovely","LEEN-doo","ES","Spanish lindo. Brazilians say it constantly: Que lindo! = How lovely!","Que lindo esse pôr do sol!","What a beautiful sunset!"],
["informação","f","information","een-for-mah-SOWNG","PAD","-tion → -ção: information → informação.","Preciso de uma informação, por favor.","I need some information, please."],
["abrir","","to open","ah-BREER","LA","Latin aperire, as in aperture (an opening). Abre a porta! = Open the door!","A loja vai abrir às nove.","The store will open at nine."],
["perceber","","to notice / to realize","pehr-seh-BEH","EN","perceive → perceber. Não percebi = I didn't notice.","Não percebi que você estava aqui.","I didn't notice you were here."],
["programa","m","program / show / plan (outing)","proh-GRAH-mah","EN","program → programa, masculine despite -a. Also a night out: Qual é o programa hoje?","Qual é o programa para hoje à noite?","What's the plan for tonight?"],
["sol","m","sun","sow (rhymes with 'cow')","LA","Latin sol, as in solar. The final l sounds like w: \"sow\". Pegar sol = sunbathe.","Hoje o sol está muito forte.","The sun is very strong today."],
["simplesmente","","simply / just","seem-plez-MEN-chee","PAD","simples + -mente = simply.","Ele simplesmente foi embora sem falar nada.","He simply left without saying anything."],
["caixa","f","box / cashier / checkout","KYE-shah","EN","case / cash box → caixa. Caixa eletrônico = ATM; o caixa = the cashier.","Coloca tudo nessa caixa.","Put everything in this box."],
["hotel","m","hotel","oh-TEW (h silent)","EN","hotel → hotel, silent h and final l like w.","O hotel fica perto da praia.","The hotel is near the beach."],
["gostar","","to like","gos-TAH","EN","gusto / disgust → gostar. Always with de: gosto de você = I like you.","Você vai gostar desse lugar.","You're going to like this place."],
["incrível","","incredible / amazing","een-KREE-vew","EN","incredible → incrível: -ble becomes -vel.","A comida estava incrível.","The food was amazing."],
["igreja","f","church","ee-GREH-zhah","LA","Latin ecclesia, as in ecclesiastical, worn down to igreja.","A igreja fica na praça central.","The church is on the main square."],
["presente","m","gift / present (time)","preh-ZEN-chee","EN","present → presente: both a gift and the here and now.","Comprei um presente para a minha mãe.","I bought a gift for my mom."],
["carta","f","letter (mail) / playing card","KAR-tah","FALSO","Not a cart! Uma carta is a letter you mail. Also a playing card: jogar cartas.","Recebi uma carta da minha avó.","I got a letter from my grandmother."],
["barco","m","boat","BAR-koo","EN","barque / bark (old sailing ship) → barco.","Fizemos um passeio de barco.","We took a boat trip."],
["loja","f","store / shop","LOH-zhah","EN","lodge → loja: a little booth for selling. Loja de roupas = clothing store.","Essa loja fecha às dez.","This store closes at ten."],
["roupa","f","clothes / clothing","HOH-pah (r at the start sounds like h)","EN","robe → roupa. Lavar roupa = do laundry.","Preciso lavar a roupa hoje.","I need to do the laundry today."],
["luta","f","fight / struggle","LOO-tah","LA","Latin lucta, as in reluctant (struggling against). A luta continua = the struggle goes on.","Ele assiste luta na TV.","He watches fights on TV."],
["câmera","f","camera","KAH-meh-rah","EN","camera → câmera. Câmera do celular = phone camera.","A câmera do meu celular quebrou.","My phone's camera broke."],
["professor","m","teacher / professor","proh-feh-SOR","FALSO","Used for ANY teacher, even in first grade, not only a university professor.","O professor passou muita lição de casa.","The teacher gave a lot of homework."],
["mostrar","","to show","mos-TRAH","EN","demonstrate → mostrar. Me mostra! = Show me!","Vou te mostrar minhas fotos da viagem.","I'll show you my trip photos."],
["reunião","f","meeting / reunion","heh-oo-nee-OWNG","EN","reunion → reunião: people re-united. Tenho reunião = I have a meeting.","A reunião começa às duas.","The meeting starts at two."],
["prova","f","test / exam / proof","PROH-vah","EN","proof / prove → prova. Prova de matemática = math test.","Amanhã tenho prova de inglês.","Tomorrow I have an English test."],
["trazer","","to bring","trah-ZEH (soft r)","LA","Latin trahere, as in tractor: something that pulls things to you. Traz! = Bring it!","Pode trazer a sobremesa?","Can you bring the dessert?"],
["olho","m","eye","OH-lyoo","SOM","\"Oh, LOOK!\" says the EYE. Olho por olho = an eye for an eye.","Abre o olho, está vindo um carro!","Watch out, a car is coming!"],
["chamado","m","call / summons / service ticket","shah-MAH-doo","PAD","From chamar: something called. In offices, abrir um chamado = open a support ticket.","Abri um chamado para consertar o computador.","I opened a ticket to fix the computer."],
["através","","through / across","ah-trah-VESS","EN","traverse → através. Através de = by means of, through.","Soube da notícia através de uma amiga.","I heard the news through a friend."],
["lei","f","law","lay","LA","Latin lex, as in legal and legislation. Lei Seca = Brazil's zero-tolerance drink-driving law.","A lei é igual para todos.","The law is the same for everyone."],
["banco","m","bank / bench","BAN-koo","EN","bank / bench → banco: both come from an old money-changer's bench.","Preciso ir ao banco antes das quatro.","I need to go to the bank before four."],
["segunda","f","Monday","seh-GOON-dah","REGRA","Weekdays are numbered from Sunday: segunda-feira = second day = Monday. Short form: segunda.","Na segunda eu começo a dieta.","On Monday I'm starting my diet."],
["tocar","","to touch / to play (instrument) / to ring","toh-KAH","EN","touch → tocar. Tocar violão = play the guitar; o telefone tocou = the phone rang.","Ele sabe tocar violão muito bem.","He can play the guitar very well."],
["mês","m","month","mess","LA","Latin mensis, as in menstrual and semester. Mês que vem = next month.","Viajo no mês que vem.","I'm traveling next month."],
["papel","m","paper / role","pah-PEW","EN","paper → papel, final l like w. Also a role: o papel principal = the lead role.","Me empresta uma folha de papel?","Can you lend me a sheet of paper?"],
["sonho","m","dream","SOH-nyoo","LA","Latin somnium, as in insomnia. Also a cream-filled doughnut sold in every padaria.","Meu sonho é conhecer o Japão.","My dream is to visit Japan."],
["bar","m","bar","bar (soft r)","EN","bar → bar. In Brazil, a boteco is a simple neighborhood bar.","Vamos tomar uma cerveja no bar?","Shall we have a beer at the bar?"],
["povo","m","people (a nation) / the public","POH-voo","LA","Latin populus, as in population and popular. O povo brasileiro = the Brazilian people.","O povo foi às ruas comemorar.","The people took to the streets to celebrate."],
["centro","m","center / downtown","SEN-troo","EN","center → centro. Ir ao centro = go downtown.","O museu fica no centro da cidade.","The museum is in the city center."],
["conversar","","to talk / to chat","kon-vehr-SAH","EN","converse → conversar. Precisamos conversar = we need to talk.","Precisamos conversar sobre a viagem.","We need to talk about the trip."],
["proteger","","to protect","proh-teh-ZHEH","EN","protect → proteger. Protetor solar = sunscreen.","Use protetor para proteger a pele.","Use sunscreen to protect your skin."],
["bebida","f","drink / beverage","beh-BEE-dah","PAD","From beber: what you drink. Bebida alcoólica = alcoholic drink.","Que bebida você vai querer?","What would you like to drink?"],
["base","f","base / basis / foundation","BAH-zee","EN","base → base, but the s sounds like z.","A base do bolo é de chocolate.","The cake's base is chocolate."],
["namorada","f","girlfriend","nah-moh-RAH-dah","SOM","\"Nah, more RAH-da!\" Cupid insists: she's his GIRLFRIEND. From namorar, to date.","Ele vai apresentar a namorada para a família.","He's going to introduce his girlfriend to the family."],
["empresa","f","company / business","em-PREH-zah","FR","French entreprise, enterprise → empresa.","Ela trabalha numa empresa de tecnologia.","She works at a tech company."],
["metade","f","half","meh-TAH-jee","SOM","\"Meh, TAH-gee\": you only get HALF the cake. Pela metade = halfway.","Comi metade da pizza sozinho.","I ate half the pizza by myself."],
["impossível","","impossible","eem-poh-SEE-vew","EN","impossible → impossível: -ble becomes -vel.","É impossível estacionar aqui.","It's impossible to park here."],
["interessante","","interesting","een-teh-reh-SAN-chee","EN","interesting → interessante: double s, ends in -ante.","Esse livro é muito interessante.","This book is very interesting."],
["cair","","to fall","kah-EER","SOM","\"Ka-EAR!\" the sound of something FALLING and smacking your ear. Caiu! = It fell!","Cuidado para não cair na escada.","Be careful not to fall on the stairs."],
["engraçado","","funny","en-grah-SAH-doo","EN","grace → engraçado: full of graceful fun. Que engraçado! = How funny!","Esse vídeo é muito engraçado.","This video is really funny."],
["dedo","m","finger / toe","DEH-doo","LA","Latin digitus, as in digit (fingers were the first calculators). Dedo do pé = toe.","Cortei o dedo cozinhando.","I cut my finger while cooking."],
["mentir","","to lie (tell lies)","men-CHEER","SOM","\"MEN-cheer\": the MEN cheer, but they're LYING. Mentira = a lie.","Não precisa mentir para mim.","You don't need to lie to me."],
["costas","f","back (of the body)","KOS-tahss","EN","coast / costal → costas: ribs line the back. Always plural: dor nas costas = back pain.","Estou com dor nas costas.","I have back pain."],
["chave","f","key","SHAH-vee","FR","French clé / clavier: keys to open things. Chave do carro = car key.","Esqueci a chave dentro de casa.","I left the key inside the house."],
["divertido","","fun / amusing","jee-vehr-CHEE-doo","EN","diverting / diversion → divertido. Foi muito divertido! = It was so much fun!","O passeio foi muito divertido.","The outing was a lot of fun."],
["escrever","","to write","es-kreh-VEH","EN","scribe / scribble → escrever. Escreve aqui seu nome.","Pode escrever seu nome aqui?","Can you write your name here?"],
["guarda","m","guard / watchman","GWAR-dah","EN","guard → guarda. Guarda-chuva = umbrella (rain guard).","O guarda abriu o portão.","The guard opened the gate."],
["apartamento","m","apartment","ah-par-tah-MEN-too","EN","apartment → apartamento. Brazilians shorten it to apê.","Meu apartamento tem dois quartos.","My apartment has two bedrooms."],
["posição","f","position","poh-zee-SOWNG","PAD","-tion → -ção: position → posição.","Qual é a sua posição no time?","What's your position on the team?"],
["céu","m","sky / heaven","SEH-oo","LA","Latin caelum, as in celestial. Céu azul = blue sky.","O céu está limpo hoje.","The sky is clear today."],
["cabo","m","cable / handle / cape (land)","KAH-boo","EN","cable → cabo. Also a cape: Cabo Frio. Ao cabo de = at the end of.","O cabo do carregador quebrou.","The charger cable broke."],
["receber","","to receive / to get","heh-seh-BEH","EN","receive → receber. Recebi sua mensagem = I got your message.","Você vai receber o pacote amanhã.","You'll receive the package tomorrow."],
["motivo","m","reason / motive","moh-CHEE-voo","EN","motive → motivo. Por que motivo? = For what reason?","Qual foi o motivo da briga?","What was the reason for the fight?"],
["ótimo","","great / excellent","AW-chee-moo","LA","Latin optimus, as in optimal and optimist. Ótimo! = Great!","Que ótimo, parabéns!","That's great, congratulations!"],
["sombra","f","shade / shadow","SOM-brah","ES","Spanish sombra, as in sombrero: the hat that makes SHADE.","Vamos sentar na sombra da árvore.","Let's sit in the shade of the tree."],
["estrada","f","road / highway","es-TRAH-dah","EN","street / strata → estrada: the Roman paved road. Pé na estrada = hit the road.","A estrada para a praia estava cheia.","The road to the beach was packed."],
["cheio","","full","SHAY-oo","SOM","\"SHAY-o\": a SHAY (cart) loaded FULL. Estou cheio = I'm full (after eating).","O ônibus está cheio, vamos esperar o próximo.","The bus is full, let's wait for the next one."],
["companhia","f","company (companionship / firm)","kom-pah-NYEE-ah","EN","company → companhia. Obrigado pela companhia = thanks for the company.","Obrigado pela companhia hoje.","Thanks for the company today."],
["horrível","","horrible / awful","oh-HEE-vew","EN","horrible → horrível: -ble becomes -vel, h silent.","O trânsito hoje está horrível.","The traffic is awful today."],
["namorado","m","boyfriend","nah-moh-RAH-doo","PAD","Masculine of namorada: the BOYfriend. Dia dos Namorados in Brazil is June 12.","O namorado dela mora em outra cidade.","Her boyfriend lives in another city."],
["norte","m","north","NOR-chee","EN","north → norte. O Norte = Brazil's Amazon region.","Belém fica no norte do Brasil.","Belém is in the north of Brazil."],
["explicar","","to explain","es-plee-KAH","EN","explain / explicit → explicar. Pode explicar de novo?","Pode explicar de novo, por favor?","Can you explain again, please?"],
["aprender","","to learn","ah-pren-DEH","EN","apprentice / apprehend → aprender: an apprentice learns.","Quero aprender a dançar forró.","I want to learn to dance forró."],
["quente","","hot / warm","KEN-chee","SOM","\"KEN-chee\": Ken and Barbie on a HOT beach. Água quente = hot water.","Cuidado, o prato está quente.","Careful, the plate is hot."],
["saia","f","skirt","SYE-ah","SOM","\"SIGH-ah\": she sighs over her new SKIRT. Also the command Saia! = Get out! (from sair).","Ela comprou uma saia azul.","She bought a blue skirt."],
["padre","m","priest","PAH-dree","FALSO","Not father in the family sense (that's pai)! Only the Catholic priest, like Spanish padre.","O padre celebrou o casamento.","The priest performed the wedding."],
["vestido","m","dress","ves-CHEE-doo","EN","vest / vestment → vestido: clothing. Vestido de noiva = wedding dress.","Ela usou um vestido vermelho na festa.","She wore a red dress to the party."],
["máquina","f","machine","MAH-kee-nah","EN","machine → máquina. Máquina de lavar = washing machine.","A máquina de lavar quebrou.","The washing machine broke."],
["parecer","","to seem / to look like","pah-reh-SEH","EN","appear → parecer. Parece que vai chover = it looks like rain.","Você parece cansado hoje.","You look tired today."],
["esquerda","f","left","es-KEHR-dah","ES","Spanish izquierda. À esquerda = on the left. Also the political Left.","Vire à esquerda no semáforo.","Turn left at the traffic light."],
["avó","f","grandmother","ah-VAW (open o)","PAD","avó (open o, like 'awe') is grandma; avô (closed o) is grandpa. Os avós = grandparents.","Minha avó faz um bolo de fubá delicioso.","My grandma makes a delicious cornmeal cake."],
["confiar","","to trust","kon-fee-AH","EN","confide / confidence → confiar. Confio em você = I trust you.","Você pode confiar nele.","You can trust him."],
["contente","","glad / pleased","kon-TEN-chee","EN","content → contente: happy with what you have.","Fiquei contente com a notícia.","I was glad about the news."],
["frio","","cold","FREE-oo","ES","Spanish frío. Estou com frio = I'm cold. Frio is also a noun: o frio.","Hoje está fazendo muito frio.","It's very cold today."],
["aonde","","where (to)","ah-ON-jee","PAD","a (to) + onde (where): to where. Aonde você vai? = Where are you going?","Aonde vocês vão nas férias?","Where are you going on vacation?"],
["aniversário","m","birthday / anniversary","ah-nee-vehr-SAH-ree-oo","EN","anniversary → aniversário, but in Brazil it mostly means birthday. Feliz aniversário!","Meu aniversário é em junho.","My birthday is in June."],
["funcionar","","to work (function) / to run","foon-see-oh-NAH","EN","function → funcionar. Não funciona = it doesn't work.","Esse controle não quer funcionar.","This remote won't work."],
["sul","m","south","sool (final l like w: 'soow')","FR","French sud, Spanish sur. Rio Grande do Sul = Big River of the South.","Faz frio no sul do Brasil.","It's cold in the south of Brazil."],
["carne","f","meat / flesh","KAR-nee","EN","carnivore / carnal → carne. Carne de porco = pork.","Eu não como carne vermelha.","I don't eat red meat."],
["vender","","to sell","ven-DEH (soft r)","EN","vendor / vending machine → vender. Vende-se = for sale.","Eles querem vender a casa.","They want to sell the house."],
["abaixo","","below / down","ah-BYE-shoo","PAD","a + baixo (low): downward. Abaixo de zero = below zero.","A temperatura ficou abaixo de zero.","The temperature dropped below zero."],
["direita","f","right (side)","jee-RAY-tah","PAD","Feminine of direito: à direita = on the right. Also the political Right.","A farmácia fica à direita.","The pharmacy is on the right."],
["cavalo","m","horse","kah-VAH-loo","EN","cavalry / cavalier → cavalo. Andar a cavalo = ride a horse.","Meu tio tem um cavalo no sítio.","My uncle has a horse at his farm."],
["área","f","area","AH-ree-ah","EN","area → área, same word with an accent on the first A, which takes the stress.","Esta área é só para funcionários.","This area is for staff only."],
["triste","","sad","TREES-chee","LA","tristis (Latin) → triste. Think of a 'tryst' that ended badly and left you SAD.","Ela ficou triste com a notícia.","She was sad about the news."],
["espécie","f","species / kind","es-PEH-see-ee","EN","species → espécie. Portuguese adds an E before S plus consonant, just like Spanish: special → especial.","Que espécie de pássaro é aquele?","What kind of bird is that?"],
["amarelo","","yellow","ah-mah-REH-loo","IMG","Picture a yellow taxi stuck in traffic: the driver yells \"AH, MARELLO!\" at a yellow light.","O táxi amarelo parou na esquina.","The yellow taxi stopped at the corner."],
["esquecer","","to forget","es-keh-SEHR","SOM","\"ESKAY, SEHR, what was I saying?\" Someone forgets the end of their sentence. Esqueci! = I forgot!","Não esqueça as chaves em casa.","Don't forget the keys at home."],
["contrário","m","opposite / contrary","kohn-TRAH-ree-oo","EN","contrary → contrário (-ary becomes -ário, like dictionary → dicionário). Ao contrário = on the contrary.","Ele sempre faz o contrário do que digo.","He always does the opposite of what I say."],
["cerveja","f","beer","sehr-VEH-zhah","LA","cervisia (Latin) gives Spanish cerveza and Portuguese cerveja. At a Brazilian bar, ask for uma cerveja gelada.","Vamos tomar uma cerveja depois do trabalho?","Shall we have a beer after work?"],
["diferença","f","difference","jee-feh-REN-sah","REGRA","difference → diferença. English -ence often becomes -ença: presence → presença.","Qual é a diferença entre os dois?","What's the difference between the two?"],
["branco","","white","BRAHN-koo","FR","blanc (French) → branco: Portuguese often turns L after a consonant into R (blank → branco).","Prefiro vinho branco com peixe.","I prefer white wine with fish."],
["mandar","","to send / to order","mahn-DAHR","EN","mandate → mandar. A boss gives a mandate, and you also mandar a message.","Pode me mandar a foto agora?","Can you send me the photo now?"],
["saúde","f","health / bless you","sah-OO-jee","FRASE","Brazilians say \"Saúde!\" both when toasting and when someone sneezes: to your HEALTH. Think salute → saúde.","Saúde! Ao nosso novo projeto!","Cheers! To our new project!"],
["tratar","","to treat / to deal with","trah-TAHR","EN","treat → tratar. Tratar de = to deal with; trata-se de = it's about.","O médico vai tratar a sua alergia.","The doctor will treat your allergy."],
["perigoso","","dangerous","peh-ree-GOH-zoo","EN","peril / perilous → perigoso. The -oso ending is the English -ous: famous → famoso.","Esse bairro é perigoso à noite.","This neighborhood is dangerous at night."],
["inteligente","","intelligent / smart","een-teh-lee-ZHEN-chee","EN","intelligent → inteligente, one L only. The final -te sounds like 'chee' in Brazil.","Seu cachorro é muito inteligente.","Your dog is very smart."],
["teste","m","test","TES-chee","EN","test → teste. Brazil adds a final E, which sounds like 'chee' after T: Internet → 'eenter-NEH-chee'.","Amanhã tenho um teste de inglês.","Tomorrow I have an English test."],
["bola","f","ball","BOH-lah","IMG","A bowl turned upside down looks like half a ball: bowl → bola. Brazil's national obsession is the bola de futebol.","As crianças jogam bola na rua.","The kids play ball in the street."],
["cliente","m","customer / client","klee-EN-chee","EN","client → cliente. Works for both sexes: o cliente, a cliente.","O cliente pediu a conta.","The customer asked for the bill."],
["mar","m","sea","MAHR (final r like a soft h in Rio)","LA","mare (Latin) → mar, as in maritime and marine. In Rio, the final R often sounds like a breathy H.","A casa fica perto do mar.","The house is near the sea."],
["dançar","","to dance","dahn-SAHR","EN","dance → dançar. The Ç is just an S sound: dança, dançar.","Você quer dançar comigo?","Do you want to dance with me?"],
["risco","m","risk","HEES-koo","EN","risk → risco. Correr o risco = to run the risk. Initial R is a breathy H.","Não vale a pena correr esse risco.","It's not worth taking that risk."],
["entender","","to understand","en-ten-DEHR","EN","Think 'intend': to understand what someone intends. Entendeu? = Got it?","Desculpa, não entendi a pergunta.","Sorry, I didn't understand the question."],
["aceitar","","to accept","ah-say-TAHR","EN","accept → aceitar (cc becomes c, -pt becomes -t). Aceita cartão? = Do you take cards?","Vocês aceitam cartão de crédito?","Do you accept credit cards?"],
["clube","m","club","KLOO-bee","EN","club → clube, with a final E. A Brazilian clube can be a social club with a pool, not just a nightclub.","Meu pai é sócio do clube.","My dad is a member of the club."],
["pobre","","poor","POH-bree","FR","pauvre (French) / poor → pobre. Coitado also works for 'poor thing'.","A família dele era pobre.","His family was poor."],
["conselho","m","advice / council","kohn-SEH-lyoo","EN","counsel → conselho. Lh sounds like the 'lli' in million.","Posso te dar um conselho?","Can I give you some advice?"],
["computador","m","computer","kohm-poo-tah-DOHR","REGRA","computer → computador. English -er for tools often becomes -dor: elevator → elevador.","Meu computador está muito lento.","My computer is very slow."],
["entrada","f","entrance / ticket / starter","en-TRAH-dah","EN","entry → entrada. Also the ticket that lets you in and the starter of a meal.","A entrada do museu é grátis hoje.","Admission to the museum is free today."],
["janela","f","window","zhah-NEH-lah","IMG","Janus, the Roman god with two faces, watches from a window: one face inside, one outside. J sounds like the S in 'pleasure'.","Pode abrir a janela, por favor?","Can you open the window, please?"],
["longo","","long","LOHN-goo","EN","long → longo. A longo prazo = in the long run. For hair or a trip, comprido also works.","Foi um dia longo e cansativo.","It was a long and tiring day."],
["totalmente","","totally","toh-tow-MEN-chee","REGRA","totally → totalmente. -mente is the -ly ending: totalmente, rapidamente, finalmente.","Concordo totalmente com você.","I totally agree with you."],
["propósito","m","purpose","proh-POH-zee-too","EN","purpose → propósito. A propósito = by the way, on purpose = de propósito.","Ele fez isso de propósito!","He did that on purpose!"],
["provar","","to taste / to try on / to prove","proh-VAHR","EN","prove → provar. You prove a dish by tasting it, and a shirt by trying it on.","Quer provar o bolo de chocolate?","Do you want to taste the chocolate cake?"],
["avô","m","grandfather","ah-VOH (closed o)","PAD","Closed avÔ = grandfather, open avÓ = grandmother. Think of grandpa's closed mouth and grandma's wide-open laugh.","Meu avô tem noventa anos.","My grandfather is ninety years old."],
["ligação","f","phone call / connection","lee-gah-SOWN (nasal)","REGRA","ligar = to call, -ção = -tion: a link-ation. Fazer uma ligação = to make a call.","Recebi uma ligação da minha mãe.","I got a call from my mom."],
["seguinte","","following / next","seh-GEEN-chee","EN","sequence / sequel → seguinte: what follows. No dia seguinte = the next day.","No dia seguinte, ele voltou.","The following day, he came back."],
["menino","m","boy","meh-NEE-noo","IMG","A MINI person: menino is a small boy. Menina is a girl.","O menino está brincando no parque.","The boy is playing in the park."],
["criar","","to create / to raise","kree-AHR","EN","create → criar. Also to raise children or animals: fui criado em Recife.","Ela quer criar o próprio negócio.","She wants to create her own business."],
["colocar","","to put / to place","koh-loh-KAHR","EN","locate / collocate → colocar: give something a location. Very common in Brazil instead of pôr.","Onde posso colocar as malas?","Where can I put the suitcases?"],
["foto","f","photo","FOH-too","EN","photo → foto. It's feminine because it's short for a fotografia.","Tira uma foto da gente!","Take a picture of us!"],
["chance","f","chance / opportunity","SHAHN-see","EN","chance → chance, same word, but feminine in Portuguese and the CH is a soft sh. Sem chance! = No way!","Me dá mais uma chance, por favor.","Give me one more chance, please."],
["verificar","","to check / to verify","veh-ree-fee-KAHR","EN","verify → verificar. -ify becomes -ificar: clarify → clarificar.","Vou verificar o horário do voo.","I'll check the flight time."],
["terrível","","terrible","teh-HEE-vew","REGRA","terrible → terrível. English -ble becomes -vel: possible → possível. Double RR is a throaty H.","O trânsito hoje está terrível.","The traffic today is terrible."],
["monte","m","pile / a lot / hill","MOHN-chee","EN","mount / mountain → monte. Um monte de = a whole pile of, a lot of.","Tenho um monte de coisas para fazer.","I have a ton of things to do."],
["pedido","m","order / request","peh-JEE-doo","SOM","pedir = to ask. A pedido is what you asked for: your order at the restaurant, PEDDLED to your table.","O garçom anotou o nosso pedido.","The waiter took our order."],
["chorar","","to cry","shoh-RAHR","SOM","A whole CHORUS of babies crying at once: chorar. Ch sounds like English sh.","O bebê começou a chorar de fome.","The baby started crying from hunger."],
["exemplo","m","example","eh-ZEM-ploo","EN","example → exemplo. Por exemplo = for example.","Pode me dar um exemplo?","Can you give me an example?"],
["rio","m","river","HEE-oo","NOME","Rio de Janeiro means 'River of January': explorers mistook the bay for a river.","Nadamos no rio no fim de semana.","We swam in the river on the weekend."],
["jeito","m","way / knack","ZHAY-too","FRASE","Brazil's famous jeitinho is the clever little way around any problem. Dar um jeito = find a way.","Não tem jeito, vamos ter que esperar.","There's no way around it, we'll have to wait."],
["início","m","beginning / start","ee-NEE-see-oo","EN","initial / initiate → início. Página inicial = home page.","No início, eu não gostava de café.","In the beginning, I didn't like coffee."],
["enorme","","huge / enormous","eh-NOHR-mee","EN","enormous → enorme. Drop the -ous and add -e.","A fila estava enorme.","The line was huge."],
["televisão","f","television","teh-leh-vee-ZOWN (nasal)","REGRA","television → televisão. -sion becomes -são: vision → visão. Everyday word: a TV ('teh-VEH').","A televisão está ligada o dia todo.","The TV is on all day."],
["socorro","m","help! (emergency)","soh-KOH-hoo","LA","succor (old English, from Latin succurrere) → socorro. Shout \"Socorro!\" only in a real emergency.","Socorro! Alguém chame uma ambulância!","Help! Somebody call an ambulance!"],
["acima","","above / up","ah-SEE-mah","IMG","A climber reaches the summit, cima: acima means above. Lá em cima = up there.","Moro no andar acima do seu.","I live on the floor above yours."],
["almoço","m","lunch","ow-MOH-soo","SOM","\"ALL MOSS, so?\" A vegan lunch of nothing but greens. Lunch is the big meal of the day in Brazil.","O almoço está pronto na mesa.","Lunch is ready on the table."],
["cartão","m","card","kahr-TOWN (nasal)","EN","card / carton → cartão. -ão makes it bigger, like a stiff card. Cartão de crédito = credit card.","Esqueci meu cartão do banco.","I forgot my bank card."],
["cozinha","f","kitchen / cuisine","koh-ZEE-nyah","LA","coquina (Latin) gives both kitchen and cozinha. Cozinha brasileira = Brazilian cuisine.","A família se reúne na cozinha.","The family gathers in the kitchen."],
["cinza","","gray / ash","SEEN-zah","IMG","Cinderella sat in the ashes: cinza is ash, and the color of ash, gray.","O céu está cinza, vai chover.","The sky is gray, it's going to rain."],
["preço","m","price","PREH-soo","EN","price → preço. Qual é o preço? = What's the price?","O preço da gasolina subiu de novo.","The price of gas went up again."],
["principal","","main / principal","preen-see-POW","EN","principal → principal, same spelling. Final L sounds like W in Brazil: 'preen-see-POW'.","Qual é a rua principal da cidade?","What's the main street in town?"],
["justo","","fair / just / tight","ZHOOS-too","EN","just → justo: fair. Also tight-fitting: a calça ficou justa.","Não é justo, eu cheguei primeiro!","That's not fair, I got here first!"],
["chá","m","tea","SHAH","SOM","Cha, chai, chá: tea travelled the world with almost the same name. Chá gelado = iced tea.","Quer um chá de camomila?","Would you like some chamomile tea?"],
["vinho","m","wine","VEE-nyoo","LA","vinum (Latin) → vinho, as in vine and vineyard. Nh sounds like the 'ny' in canyon.","Vamos abrir uma garrafa de vinho.","Let's open a bottle of wine."],
["relatório","m","report","heh-lah-TOH-ree-oo","EN","relate → relatório: a document that relates what happened. -ório like laboratory → laboratório.","Preciso terminar o relatório até sexta.","I need to finish the report by Friday."],
["necessário","","necessary","neh-seh-SAH-ree-oo","EN","necessary → necessário. -ary becomes -ário again.","Não é necessário trazer nada.","It's not necessary to bring anything."],
["par","m","pair / even (number)","PAHR","EN","pair → par. Um par de sapatos = a pair of shoes. Número par = even number.","Comprei um par de tênis novo.","I bought a new pair of sneakers."],
["tia","f","aunt","CHEE-ah","SOM","Your aunt invites you to TEA: tia sounds like 'chee-ah' in Brazil. Kids also call teachers tia.","Minha tia mora em Salvador.","My aunt lives in Salvador."],
["maravilhoso","","wonderful / marvelous","mah-rah-vee-LYOH-zoo","EN","marvelous → maravilhoso: -ous becomes -oso again. A Marvel movie that's maravilhoso.","Que dia maravilhoso na praia!","What a wonderful day at the beach!"],
["celular","m","cell phone","seh-loo-LAHR","EN","cellular → celular. Brazilians never say 'telemóvel'; it's always o celular.","Meu celular está sem bateria.","My phone is out of battery."],
["ilha","f","island","EE-lyah","LA","insula (Latin) gave isle, island and ilha. Lh sounds like 'lli' in million.","Florianópolis fica numa ilha.","Florianópolis is on an island."],
["subir","","to go up / to climb","soo-BEER","IMG","A SUBmarine coming up to the surface: subir is to go up. Its opposite is descer.","Vamos subir de escada ou de elevador?","Shall we go up by stairs or elevator?"],
["opinião","f","opinion","oh-pee-nee-OWN (nasal)","REGRA","opinion → opinião. -ion becomes -ião: religion → religião. Na minha opinião = in my opinion.","Na minha opinião, o filme é ótimo.","In my opinion, the movie is great."],
["terminar","","to finish / to end","tehr-mee-NAHR","EN","terminate → terminar. Also to break up: terminar com alguém.","Você já terminou o trabalho?","Have you finished the work yet?"],
["fato","m","fact","FAH-too","EN","fact → fato (Portugal writes facto). De fato = in fact.","É um fato: ninguém gosta de segunda.","It's a fact: nobody likes Mondays."],
["braço","m","arm","BRAH-soo","EN","bracelet goes around the braço. Also brace: you brace yourself with your arms.","Machuquei o braço jogando vôlei.","I hurt my arm playing volleyball."],
["saco","m","bag / sack","SAH-koo","EN","sack → saco. Slang: que saco! = what a pain!","Coloca o lixo no saco preto.","Put the trash in the black bag."],
["lembrar","","to remember","lem-BRAHR","LA","memorare (Latin) slowly became lembrar: the M turned into L. Think 'remember' with the re- cut off and the M softened.","Você lembra o nome dele?","Do you remember his name?"],
["senão","","otherwise / or else","see-NOWN (nasal)","PAD","se + não = if not. Corre, senão você perde o ônibus: run, if not you'll miss the bus.","Leva o casaco, senão vai passar frio.","Take your coat, otherwise you'll be cold."],
["série","f","series / grade (school)","SEH-ree-ee","EN","series → série. Also a TV show you binge, and a school grade: quinta série.","Qual série você está assistindo agora?","Which series are you watching now?"],
["geladeira","f","fridge","zheh-lah-DAY-rah","PAD","gelado = ice-cold, -eira = the thing that holds it. The gelato-maker in your kitchen.","Tem suco na geladeira.","There's juice in the fridge."],
["junto","","together / next to","ZHOON-too","EN","joint / join → junto. Junto com = together with. Juntos when you're more than one.","Moro junto com dois amigos.","I live together with two friends."],
["discutir","","to argue / to discuss","jees-koo-CHEER","FALSO","Looks like discuss, but in Brazil it often means to ARGUE angrily. Discutir a relação = to have 'the talk'.","Eles vivem discutindo por bobagem.","They're always arguing over nothing."],
["rádio","m","radio","HAH-jee-oo","EN","radio → rádio. Initial R is a breathy H, and di sounds like 'jee'.","Meu pai ouve rádio no carro.","My dad listens to the radio in the car."],
["silêncio","m","silence","see-LEN-see-oo","REGRA","silence → silêncio. English -ence often becomes -êncio or -ência.","Silêncio, o bebê está dormindo!","Quiet, the baby is sleeping!"],
["peça","f","piece / part / play","PEH-sah","EN","piece → peça. Also a theater play and a spare part: peça de carro.","Falta uma peça no quebra-cabeça.","A piece of the puzzle is missing."],
["escolher","","to choose","es-koh-LYEHR","SOM","At ESCOLA (school), you choose your seat on day one: escolher. Escolha = a choice.","Pode escolher qualquer sobremesa.","You can choose any dessert."],
["limpar","","to clean","leem-PAHR","LA","limpidus (Latin, clear) → limpar. A limpid pool is perfectly clean.","Preciso limpar o meu quarto hoje.","I need to clean my room today."],
["evitar","","to avoid","eh-vee-TAHR","LA","evitare (Latin) → evitar, as in inevitable: what can't be avoided.","Tento evitar açúcar à noite.","I try to avoid sugar at night."],
["verão","m","summer","veh-ROWN (nasal)","LA","ver (Latin, spring) → verão, the season that follows. Vernal equinox shares the root. Brazil's verão runs December to March.","No verão, a praia fica lotada.","In summer, the beach gets packed."],
["leve","","light (weight)","LEH-vee","EN","levitate / lever → leve: so light it floats. The opposite is pesado.","A mala está leve, posso carregar.","The suitcase is light, I can carry it."],
["memória","f","memory","meh-MOH-ree-ah","EN","memory → memória. Memória do celular = phone storage.","Minha avó tem uma memória incrível.","My grandmother has an incredible memory."],
["azul","","blue","ah-ZOOW","SOM","Azure → azul, the blue of the sky. Final L sounds like W: 'ah-ZOOW'.","O céu está bem azul hoje.","The sky is really blue today."],
["calça","f","pants / trousers","KOW-sah","IMG","A cowboy in tight pants: KOW-sah. Brazil uses the singular, a calça, for one pair.","Essa calça jeans ficou apertada.","These jeans are too tight."],
["restaurante","m","restaurant","hes-tow-RAHN-chee","EN","restaurant → restaurante, with a final E. The first R is a breathy H.","Esse restaurante tem comida mineira.","This restaurant serves food from Minas Gerais."],
["comum","","common / ordinary","koh-MOON (nasal)","EN","common → comum. Em comum = in common.","Temos muitas coisas em comum.","We have a lot in common."],
["estação","f","station / season","es-tah-SOWN (nasal)","REGRA","station → estação: initial S gets an E, -tion becomes -ção. Also the four seasons.","A estação de metrô fica ali.","The subway station is over there."],
["vídeo","m","video","VEE-jee-oo","EN","video → vídeo. Brazilian 'de' sounds like 'jee'.","Ela mandou um vídeo engraçado.","She sent a funny video."],
["preparar","","to prepare","preh-pah-RAHR","EN","prepare → preparar. Verbs from English -are often just change to -ar.","Vou preparar o jantar agora.","I'm going to prepare dinner now."],
["ocupado","","busy / occupied","oh-koo-PAH-doo","EN","occupied → ocupado. A busy person is occupied: estou ocupado agora.","Desculpa, estou ocupado agora.","Sorry, I'm busy right now."],
["duro","","hard / tough / broke","DOO-roo","EN","durable → duro. Slang: estar duro = to be broke, with no money.","Esse pão está duro como pedra.","This bread is as hard as a rock."],
["igual","","equal / the same","ee-GWOW","EN","equal → igual. Igualzinho = exactly the same.","Seu tênis é igual ao meu.","Your sneakers are the same as mine."],
["inteiro","","whole / entire","een-TAY-roo","EN","entire / integer → inteiro. O dia inteiro = the whole day.","Dormi o dia inteiro no domingo.","I slept the whole day on Sunday."],
["dúvida","f","doubt / question","DOO-vee-dah","EN","dubious / doubt → dúvida. In class, tenho uma dúvida simply means 'I have a question'.","Professor, tenho uma dúvida.","Teacher, I have a question."],
["gelo","m","ice","ZHEH-loo","IT","gelato (Italian) is ice cream; gelo is plain ice. Com gelo? = With ice?","Quer gelo no refrigerante?","Do you want ice in your soda?"],
["bem-vindo","","welcome","beng-VEEN-doo","PAD","bem (well) + vindo (come): well-come, welcome. Seja bem-vindo! = Welcome!","Seja bem-vindo à nossa casa!","Welcome to our home!"],
["universidade","f","university","oo-nee-vehr-see-DAH-jee","REGRA","university → universidade. -ty becomes -dade: city → cidade, quality → qualidade.","Ela estuda na universidade federal.","She studies at the federal university."],
["copo","m","glass / cup (for drinking)","KOH-poo","IMG","A cop stops you for drinking: he grabs your copo. It's the drinking glass; vidro is the material.","Me dá um copo d'água, por favor.","Give me a glass of water, please."],
["vermelho","","red","vehr-MEH-lyoo","LA","vermiculus (Latin, little worm): red dye was made from tiny insects, like vermilion.","O sinal ficou vermelho.","The light turned red."],
["responder","","to answer / to reply","hes-pohn-DEHR","EN","respond → responder. Responder uma mensagem = to reply to a message.","Ele ainda não respondeu minha mensagem.","He still hasn't answered my message."],
["parque","m","park","PAHR-kee","EN","park → parque, with -que for the K sound. Parque Ibirapuera is São Paulo's big park.","Vamos correr no parque amanhã cedo?","Shall we run in the park tomorrow morning?"],
["paciente","","patient","pah-see-EN-chee","EN","patient → paciente. Both the adjective (calm) and the noun (hospital patient).","Seja paciente, ele já vem.","Be patient, he's coming."],
["quão","","how (+ adjective)","KWOWN (nasal)","PAD","quanto (how much) shrunk to quão. Formal; in speech Brazilians prefer como or o quanto.","Você não imagina quão difícil foi.","You can't imagine how hard it was."],
["arte","f","art","AHR-chee","EN","art → arte. Final -te sounds like 'chee' in Brazil.","Ela adora arte moderna.","She loves modern art."],
["visita","f","visit / visitor","vee-ZEE-tah","EN","visit → visita. Also the person: temos visita hoje = we have guests today.","Recebemos uma visita inesperada.","We got an unexpected visit."],
["buraco","m","hole","boo-RAH-koo","SOM","A BURROW you dig is a buraco. Brazilian streets are famous for their buracos.","Cuidado com o buraco na calçada!","Watch out for the hole in the sidewalk!"],
["cantar","","to sing","kahn-TAHR","EN","chant / cantata → cantar. Cantor = singer.","Ela canta muito bem.","She sings really well."],
["sucesso","m","success / hit","soo-SEH-soo","EN","success → sucesso. A song that's a sucesso is a hit.","A festa foi um sucesso!","The party was a success!"],
["pegar","","to take / to grab / to catch","peh-GAHR","IMG","Hang your coat on a PEG: pegar is to grab it. Pegar o ônibus = to catch the bus.","Vou pegar o ônibus das oito.","I'm going to catch the eight o'clock bus."],
["caminhão","m","truck","kah-mee-NYOWN (nasal)","PAD","caminho (road) + -ão (big): the big thing on the road, a truck.","O caminhão bloqueou a rua inteira.","The truck blocked the whole street."],
["parede","f","wall (inside)","pah-REH-jee","EN","partition / parapet → parede: the wall between rooms. A city or garden wall is muro.","Pendurei o quadro na parede.","I hung the picture on the wall."],
["devagar","","slowly","jee-vah-GAHR","SOM","Imagine a slow-moving VAGRANT shuffling: devagar. Devagar e sempre = slow and steady.","Fala mais devagar, por favor.","Speak more slowly, please."],
["troca","f","exchange / swap","TROH-kah","SOM","Think 'trade': troca is a swap. Trocar = to change or exchange.","A loja aceita troca em até trinta dias.","The store accepts exchanges within thirty days."],
["bala","f","candy / bullet","BAH-lah","FALSO","Not a ball (that's bola)! In Brazil, bala is hard candy, and also a bullet. Context saves you.","Quer uma bala de menta?","Want a mint candy?"],
["férias","f","vacation / holidays","FEH-ree-ahs","LA","feriae (Latin, holy days) → férias, always plural. Also gives 'fair' and feriado (holiday).","Vou viajar nas férias de julho.","I'm traveling during the July vacation."],
["estrela","f","star","es-TREH-lah","LA","stella (Latin) → estrela, with E added before ST: stellar star.","Hoje dá para ver muitas estrelas.","You can see lots of stars tonight."],
["animal","m","animal","ah-nee-MOW","EN","animal → animal, same spelling. Final L sounds like W. Slang: animal! = awesome!","Qual é o seu animal favorito?","What's your favorite animal?"],
["achar","","to think / to find","ah-SHAHR","FRASE","Acho que sim = I think so. It's what you find in your mind. Achei as chaves = I found the keys.","Não acho minha carteira em lugar nenhum.","I can't find my wallet anywhere."],
["perna","f","leg","PEHR-nah","SOM","A long-legged PERson's leg. Pernas cruzadas = crossed legs.","Estou com dor na perna.","My leg hurts."],
["som","m","sound","SOHNG (nasal)","LA","sonus (Latin) → som, as in sonic. Also the sound system: liga o som!","Abaixa o som, por favor.","Turn the sound down, please."],
["edifício","m","building","eh-jee-FEE-see-oo","EN","edifice → edifício. Prédio is the everyday word in Brazil.","O edifício tem trinta andares.","The building has thirty floors."],
["enviar","","to send","en-vee-AHR","EN","envoy (someone sent) → enviar. More formal than mandar: enviar um e-mail.","Vou enviar o arquivo por e-mail.","I'll send the file by email."],
["lua","f","moon","LOO-ah","LA","luna (Latin) → lua: Portuguese often drops an N between vowels. Lunar is the English adjective.","A lua está cheia hoje.","The moon is full tonight."],
["casaco","m","coat / jacket","kah-ZAH-koo","SOM","A coat in a CASE: casaco. Leva um casaco, vai esfriar!","Leva um casaco, vai esfriar à noite.","Bring a jacket, it'll get cold at night."],
["começo","m","beginning","koh-MEH-soo","PAD","começar (to begin) → começo. Do começo = from the start.","Vamos ver o filme desde o começo.","Let's watch the movie from the beginning."],
["parceiro","m","partner","pahr-SAY-roo","EN","partner → parceiro. Also slang for buddy: e aí, parceiro?","Ele é meu parceiro de negócios.","He's my business partner."],
["imaginar","","to imagine","ee-mah-zhee-NAHR","EN","imagine → imaginar. Imagina! = Don't mention it! (after thanks).","Não consigo imaginar a vida sem música.","I can't imagine life without music."],
["simpático","","nice / friendly","seem-PAH-chee-koo","FALSO","Not sympathetic! Simpático means friendly and pleasant. 'Sympathetic' is solidário.","O vendedor foi muito simpático.","The salesman was very friendly."],
["cor","f","color","KOHR","LA","color (Latin) shrank to cor. De que cor? = What color?","Qual é a sua cor preferida?","What's your favorite color?"],
["doce","","sweet / dessert","DOH-see","IT","dolce (Italian) → doce. As a noun, um doce is a sweet treat.","Esse café está doce demais.","This coffee is too sweet."],
["líder","m","leader","LEE-dehr","EN","leader → líder. Works for both sexes: o líder, a líder.","Ela é a líder da equipe.","She's the team leader."],
["ônibus","m","bus","OH-nee-boos","LA","omnibus (Latin, for everyone) → ônibus. English cut it to 'bus'; Brazil kept the front. Portugal says autocarro.","O ônibus está atrasado de novo.","The bus is late again."],
["objetivo","m","goal / objective","ohb-zheh-CHEE-voo","EN","objective → objetivo. Qual é o seu objetivo? = What's your goal?","Meu objetivo é falar português fluente.","My goal is to speak fluent Portuguese."],
["exatamente","","exactly","eh-zah-tah-MEN-chee","REGRA","exact + -mente (-ly) = exactly. Isso mesmo also works for 'exactly!'.","É exatamente isso que eu queria.","That's exactly what I wanted."],
["voar","","to fly","voh-AHR","LA","volare (Latin/Italian) → voar: the L dropped out. Voo = flight.","Tenho medo de voar.","I'm afraid of flying."],
["carreira","f","career","kah-HAY-rah","EN","career → carreira. Originally a racecourse: your career is the race you run.","Ela quer seguir carreira na medicina.","She wants to pursue a career in medicine."],
["limpo","","clean","LEEM-poo","LA","limpid (clear) → limpo. Ficha limpa = clean record.","A casa está limpa e cheirosa.","The house is clean and smells nice."],
["árvore","f","tree","AHR-voh-ree","LA","arbor (Latin) → árvore: arboretum, Arbor Day. B became V.","Plantamos uma árvore no quintal.","We planted a tree in the backyard."],
["preparado","","prepared / ready","preh-pah-RAH-doo","EN","prepared → preparado. -ed becomes -ado: organized → organizado.","Você está preparado para a prova?","Are you prepared for the exam?"],
["demorar","","to take long / to be late","jee-moh-RAHR","EN","demur / delay → demorar. Não demora! = Don't take long!","A comida vai demorar meia hora.","The food will take half an hour."],
["dança","f","dance","DAHN-sah","EN","dance → dança. Samba, forró, frevo: Brazil has a dança for every region.","O samba é uma dança brasileira.","Samba is a Brazilian dance."],
["faculdade","f","college / faculty","fah-kool-DAH-jee","REGRA","faculty → faculdade (-ty → -dade). Fazer faculdade = to go to college.","Ele entrou na faculdade de direito.","He got into law school."],
["imagem","f","image / picture","ee-MAH-zheng","REGRA","image → imagem. English -age often becomes -agem: message → mensagem.","A imagem está muito escura.","The picture is very dark."],
["conhecido","","known / acquaintance","koh-nyeh-SEE-doo","PAD","conhecer (to know) → conhecido. As a noun, an acquaintance: é só um conhecido.","Ele é um cantor muito conhecido.","He's a very well-known singer."],
["nariz","m","nose","nah-REES","LA","nares (Latin, nostrils) → nariz, as in nasal. The final Z sounds like S.","Estou com o nariz entupido.","My nose is stuffed up."],
["cortar","","to cut","kohr-TAHR","IMG","A CORD being cut with scissors: cortar. Cortar o cabelo = to get a haircut.","Preciso cortar o cabelo.","I need to get my hair cut."],
["sobreviver","","to survive","soh-bree-vee-VEHR","PAD","sobre (over) + viver (live): to live over the danger, survive.","Ninguém sabe como ele sobreviveu.","Nobody knows how he survived."],
["preto","","black","PREH-too","SOM","A PRETTY black dress: preto is the everyday word for black in Brazil.","Ela usa sempre roupa preta.","She always wears black clothes."],
["cadeira","f","chair","kah-DAY-rah","LA","cathedra (Latin) → cadeira: a cathedral is where the bishop's chair stands.","Puxa uma cadeira e senta aqui.","Pull up a chair and sit here."],
["peixe","m","fish","PAY-shee","LA","piscis (Latin) → peixe. Pisces is the fish sign. X sounds like sh.","Hoje tem peixe frito no almoço.","Today there's fried fish for lunch."],
["calor","m","heat / hot weather","kah-LOHR","LA","calor (Latin) → calorie, the unit of heat. Que calor! = It's so hot!","Que calor! Liga o ventilador.","It's so hot! Turn on the fan."],
["partido","m","political party / broken","pahr-CHEE-doo","FALSO","A partido is a political party, never a fun one (that's festa). Also 'broken': partido ao meio.","Ele não é de nenhum partido.","He doesn't belong to any party."],
["voo","m","flight","VOH-oo","PAD","voar (to fly) → voo. Voo direto = direct flight.","Nosso voo sai às seis da manhã.","Our flight leaves at six in the morning."],
["visão","f","vision / eyesight / view","vee-ZOWN (nasal)","REGRA","vision → visão. -sion becomes -são again.","Ele tem problema de visão.","He has a vision problem."],
["controlar","","to control","kohn-troh-LAHR","EN","control → controlar. Controle remoto = remote control.","Tenta controlar a sua raiva.","Try to control your anger."],
["fechar","","to close / to shut","feh-SHAHR","SOM","FETCH the key, we're closing! Fechado = closed, on every shop door.","A farmácia fecha às dez.","The pharmacy closes at ten."],
["gritar","","to shout / to scream","gree-TAHR","SOM","Through GRITted teeth, then he bursts out shouting: gritar. Grito = scream.","Não precisa gritar, eu estou ouvindo.","No need to shout, I can hear you."],
["gato","m","cat / handsome guy","GAH-too","ES","gato (Spanish) and gato (Portuguese) are the same cat. Slang: que gato! = what a hottie!","O gato dorme no sofá o dia todo.","The cat sleeps on the couch all day."],
["canção","f","song","kahn-SOWN (nasal)","FR","chanson (French) → canção. Música is the everyday word for a song.","Essa canção me lembra a infância.","This song reminds me of my childhood."],
["interior","m","countryside / interior","een-teh-ree-OHR","FALSO","Literally 'interior', but in Brazil o interior is the countryside, anywhere away from the coast or capital.","Meus avós moram no interior.","My grandparents live in the countryside."],
["estilo","m","style","es-CHEE-loo","EN","style → estilo: E added before ST, -yle becomes -ilo.","Gosto do seu estilo de vestir.","I like your style of dressing."],
["relógio","m","clock / watch","heh-LOH-zhee-oo","LA","horologium (Latin) → relógio: the 'ho' fell off. Horology is the study of clocks.","Meu relógio está adiantado.","My watch is fast."],
["cuidar","","to take care of","kwee-DAHR","SOM","\"QUICK, DAHR-ling, take care of the baby!\" Always with de: cuidar de alguém. Cuidado! = Careful!","Quem vai cuidar do cachorro?","Who's going to take care of the dog?"],
["verde","","green","VEHR-jee","EN","verdant / verdure → verde. Brazil's flag is verde e amarelo.","As folhas ainda estão verdes.","The leaves are still green."],
["floresta","f","forest","floh-RES-tah","EN","forest → floresta: an L sneaked in. Floresta Amazônica = Amazon rainforest.","A floresta amazônica é enorme.","The Amazon rainforest is huge."],
["total","","total","toh-TOW","EN","total → total, same spelling, final L as W. No total = in total.","O total deu cem reais.","The total came to a hundred reais."],
["ponte","f","bridge","POHN-chee","LA","pons (Latin) → ponte, as in pontoon and pontiff (bridge-builder). Feminine in Portuguese.","A ponte Rio-Niterói é muito longa.","The Rio-Niterói bridge is very long."],
["diretor","m","director / principal","jee-reh-TOHR","EN","director → diretor (Brazil drops the C). Also the school principal.","O diretor chamou os pais na escola.","The principal called the parents to school."],
["praia","f","beach","PRAH-yah","SOM","Lying on the beach, you PRAY the sun stays out: praia. Vamos à praia!","Vamos para a praia no sábado?","Shall we go to the beach on Saturday?"],
["língua","f","tongue / language","LEEN-gwah","LA","lingua (Latin) → língua: linguistics, bilingual. Both the tongue in your mouth and the language.","Português é uma língua bonita.","Portuguese is a beautiful language."],
["construir","","to build / to construct","kohns-troo-EER","EN","construct → construir. Construção = construction.","Eles vão construir um prédio aqui.","They're going to build a building here."],
["banda","f","band (music)","BAHN-dah","EN","band → banda. Qual é a sua banda favorita?","A banda toca no bar toda sexta.","The band plays at the bar every Friday."],
["rapidamente","","quickly","hah-pee-dah-MEN-chee","REGRA","rapid + -mente = rapidly. Initial R is a breathy H.","Ele respondeu rapidamente.","He answered quickly."],
["busca","f","search","BOOS-kah","PAD","buscar (to fetch, search) → busca. Fazer uma busca no Google.","A polícia fez uma busca na casa.","The police searched the house."],
["ouvido","m","ear (inner) / hearing","oh-VEE-doo","PAD","ouvir (to hear) → ouvido, the organ you hear with. The outer ear is orelha.","Estou com dor de ouvido.","I have an earache."],
["rosto","m","face","HOHS-too","IMG","The ROSTrum is where a speaker shows his face to the crowd: rosto. Cara is the casual word.","Lave o rosto com água fria.","Wash your face with cold water."],
["mudança","f","change / move (house)","moo-DAHN-sah","PAD","mudar (to change) → mudança. Also moving house: caminhão de mudança = moving truck.","A mudança é na semana que vem.","The move is next week."],
["época","f","era / time / season","EH-poh-kah","EN","epoch → época. Naquela época = back then.","Naquela época, não tinha celular.","Back then, there were no cell phones."],
["fonte","f","source / fountain / font","FOHN-chee","EN","fountain / font → fonte. Water springs from it, and news comes from a fonte.","Qual é a fonte dessa notícia?","What's the source of this news?"],
["sentimento","m","feeling","sen-chee-MEN-too","EN","sentiment → sentimento. -ment becomes -mento: moment → momento.","Não sei explicar esse sentimento.","I can't explain this feeling."],
["cansado","","tired","kahn-SAH-doo","SOM","I CAN'T, SAD-o, I'm too tired: cansado. Cansada for a woman.","Estou muito cansado hoje.","I'm very tired today."],
["aula","f","class / lesson","OW-lah","IMG","A university AULA is the lecture hall, like an auditorium; today it means the class itself.","A aula começa às oito.","Class starts at eight."],
["rico","","rich","HEE-koo","EN","rich → rico. Initial R is a breathy H. Also rich in: rico em ferro.","Ele ficou rico vendendo software.","He got rich selling software."],
["acordar","","to wake up / to agree","ah-kohr-DAHR","FRASE","An alarm sets the day's ACCORD: acordar is to wake up. Acorda! = Wake up!","Acordo às seis todos os dias.","I wake up at six every day."],
["humano","","human","oo-MAH-noo","EN","human → humano. The H is silent. Ser humano = human being.","Errar é humano.","To err is human."],
["atrasado","","late / delayed","ah-trah-ZAH-doo","PAD","atrás (behind) → atrasado: left behind. Desculpa, estou atrasado!","Desculpa, estou atrasado de novo.","Sorry, I'm late again."],
["agir","","to act","ah-ZHEER","LA","agere (Latin) → agir, as in agent and agile. Aja rápido! = Act fast!","Precisamos agir antes que seja tarde.","We need to act before it's too late."],
["rir","","to laugh","HEER","LA","ridere (Latin) → rir: ridiculous, deride. Initial R is a breathy H.","Ele me faz rir muito.","He makes me laugh a lot."],
["posto","m","station / post","POHS-too","EN","post → posto. Posto de gasolina = gas station, posto de saúde = health clinic.","Vamos parar no posto para abastecer.","Let's stop at the gas station to fill up."],
["agradável","","pleasant / nice","ah-grah-DAH-vew","REGRA","agree → agradar (to please) → agradável: -ble becomes -vel, agreeable.","A noite está agradável.","The evening is pleasant."],
["jornal","m","newspaper / news","zhohr-NOW","FALSO","Not a journal! Um jornal is a newspaper, and the TV news. A diary is diário.","Meu avô lê o jornal todo dia.","My grandfather reads the newspaper every day."],
["interesse","m","interest","een-teh-REH-see","EN","interest → interesse. Careful: interest on a loan is juros, not interesse.","Ele tem muito interesse em história.","He has a lot of interest in history."],
["guerra","f","war","GEH-hah","FR","guerre (French) / guerrilla → guerra. The double RR is a throaty H.","Meu avô lutou na guerra.","My grandfather fought in the war."],
["decidir","","to decide","deh-see-JEER","EN","decide → decidir. Brazilian 'di' sounds like 'jee'.","Ainda não decidi o que vou pedir.","I still haven't decided what to order."],
["esperto","","clever / smart / sly","es-PEHR-too","FALSO","Not quite an expert: esperto is street-smart, quick-witted, sometimes a bit sly.","Esse menino é esperto demais.","That kid is way too clever."],
["classe","f","class","KLAH-see","EN","class → classe. Classe média = middle class; classe executiva = business class.","Viajamos de classe econômica.","We traveled in economy class."],
["casado","","married","kah-ZAH-doo","PAD","casa (house) + -ado: married people set up a house together. Casar = to marry.","Ele é casado e tem dois filhos.","He's married and has two kids."],
["caro","","expensive / dear","KAH-roo","IT","caro (Italian) means both dear and pricey, exactly like Portuguese. Que caro! = So expensive!","Esse restaurante é caro demais.","This restaurant is too expensive."],
["leite","m","milk","LAY-chee","SOM","Café com leite sounds like a café LATTE: leite is milk.","Quer leite no café?","Do you want milk in your coffee?"],
["mercado","m","market / grocery store","mehr-KAH-doo","EN","market / merchant → mercado. Supermercado = supermarket.","Vou ao mercado comprar arroz.","I'm going to the store to buy rice."],
["gênero","m","gender / genre / kind","ZHEH-neh-roo","EN","gender / genre → gênero. Gêneros alimentícios = foodstuffs.","Que gênero de música você gosta?","What genre of music do you like?"],
["escuro","","dark","es-KOO-roo","EN","obscure → escuro: hidden in the dark. Escuridão = darkness.","O quarto está escuro, acende a luz.","The room is dark, turn on the light."],
["desaparecer","","to disappear","jee-zah-pah-reh-SEHR","EN","disappear → desaparecer. des- = dis-, aparecer = appear.","Meu guarda-chuva desapareceu de novo.","My umbrella disappeared again."],
["levantar","","to lift / to raise / to get up","leh-vahn-TAHR","EN","lever / levitate → levantar. Levantar cedo = to get up early.","Ele levantou a mão para perguntar.","He raised his hand to ask."],
["crescer","","to grow","kreh-SEHR","EN","crescent / crescendo → crescer: the moon grows bigger. Quando crescer = when I grow up.","Seu filho cresceu muito!","Your son has grown a lot!"],
["fome","f","hunger","FOH-mee","LA","fames (Latin) → fome, as in famine. Estou com fome = I'm hungry.","Estou morrendo de fome.","I'm starving."],
["servir","","to serve / to fit","sehr-VEER","EN","serve → servir. Also for clothes: não serve = it doesn't fit.","Esse vestido não serve mais em mim.","This dress doesn't fit me anymore."],
["resultado","m","result","heh-zool-TAH-doo","EN","result → resultado. Qual foi o resultado do jogo?","Qual foi o resultado do exame?","What was the result of the exam?"],
["dor","f","pain / ache","DOHR","LA","dolor (Latin) → dor, as in dolorous. Dor de cabeça = headache.","Estou com dor de cabeça.","I have a headache."],
["solução","f","solution","soh-loo-SOWN (nasal)","REGRA","solution → solução. -tion becomes -ção.","Não vejo outra solução.","I don't see another solution."],
["data","f","date","DAH-tah","FALSO","Not data! A data is a calendar date. Data de nascimento = date of birth. Data in English is dados.","Qual é a data da festa?","What's the date of the party?"],
["garrafa","f","bottle","gah-HAH-fah","SOM","A GIRAFFE has a neck as long as a bottle's: garrafa.","Comprei uma garrafa de água.","I bought a bottle of water."],
["bolo","m","cake","BOH-loo","IMG","A round BOWL-shaped cake: bolo. Bolo de cenoura is Brazil's favorite.","Fiz um bolo de cenoura com chocolate.","I made a carrot cake with chocolate."],
["propriedade","f","property","proh-pree-eh-DAH-jee","REGRA","property → propriedade. -ty becomes -dade once more.","Essa fazenda é propriedade da família.","This farm is family property."],
["sede","f","thirst / headquarters","SEH-jee","PAD","Closed 'SEH-jee' = thirst (estou com sede). Open 'SEH-jee' = a company's headquarters. Same spelling!","Me dá água, estou com sede.","Give me water, I'm thirsty."],
["sensação","f","sensation / feeling","sen-sah-SOWN (nasal)","REGRA","sensation → sensação. Tenho a sensação de que... = I have a feeling that...","Tenho a sensação de que vai chover.","I have a feeling it's going to rain."],
["futebol","m","soccer","foo-cheh-BOW","EN","football → futebol, spelled the way Brazilians say it. In Brazil it always means soccer.","Domingo tem futebol na TV.","There's soccer on TV on Sunday."],
["bilhete","m","note / ticket","bee-LYEH-chee","EN","billet → bilhete. In Brazil, mostly a short note: deixei um bilhete na geladeira.","Deixei um bilhete na geladeira.","I left a note on the fridge."],
["cinema","m","movie theater / cinema","see-NEH-mah","EN","cinema → cinema. Masculine, despite the final A.","Vamos ao cinema hoje à noite?","Shall we go to the movies tonight?"],
["vento","m","wind","VEN-too","EN","vent / ventilate → vento: the wind ventilates the city.","Está ventando muito, cuidado com o vento.","It's very windy, careful with the wind."],
["táxi","m","taxi","TAHK-see","EN","taxi → táxi. In Brazil, most people now call a ride through an app instead.","Vamos pegar um táxi até o hotel.","Let's take a taxi to the hotel."],
["quinta-feira","f","Thursday","KEEN-tah FAY-rah","REGRA","quinta = fifth: counting from Sunday, Thursday is the fifth day. Usually just quinta.","A reunião é na quinta-feira.","The meeting is on Thursday."],
["chapéu","m","hat","shah-PEH-oo","FR","chapeau (French) → chapéu. Ch sounds like sh in both.","Use chapéu para se proteger do sol.","Wear a hat to protect yourself from the sun."],
["mexer","","to move / to touch / to stir","meh-SHEHR","IMG","MIX the batter: mexer is to stir. Não mexe nisso! = Don't touch that!","Não mexe no meu celular!","Don't touch my phone!"],
["legal","","cool / nice / legal","leh-GOW","FALSO","Means legal too, but Brazilians use legal all day as 'cool, nice': que legal! = how cool!","Que legal! Adorei o presente.","How cool! I loved the present."],
["dever","","must / to owe / duty","deh-VEHR","EN","debt → dever: you must pay what you owe. Dever de casa = homework.","Você deve descansar um pouco.","You should rest a bit."],
["porco","m","pig / pork","POHR-koo","EN","pork → porco. Also an insult for someone messy.","Na fazenda tem galinha e porco.","On the farm there are chickens and a pig."],
["natural","","natural","nah-too-ROW","EN","natural → natural, same spelling. Suco natural = freshly squeezed juice.","Prefiro suco natural, sem açúcar.","I prefer fresh juice, without sugar."],
["estudar","","to study","es-too-DAHR","EN","study → estudar: E before ST, -y becomes -ar.","Preciso estudar para a prova.","I need to study for the test."],
["partida","f","match (game) / departure","pahr-CHEE-dah","PAD","partir (to leave) → partida: the departure. In sport, the match: partida de futebol.","A partida terminou empatada.","The match ended in a draw."],
["oeste","m","west","oh-ES-chee","EN","west → oeste. Faroeste (far west) = a Western movie.","O sol se põe no oeste.","The sun sets in the west."],
["baile","m","ball / dance party","BYE-lee","SOM","Say BYE to your shoes at the end of the baile. Baile funk is a Rio party.","Vamos ao baile de formatura?","Shall we go to the prom?"],
["aeroporto","m","airport","ah-eh-roh-POHR-too","PAD","aero (air) + porto (port): airport, piece by piece.","Chegamos ao aeroporto às cinco.","We arrived at the airport at five."],
["mentira","f","lie","men-CHEE-rah","SOM","The MEN TEAR up the papers to hide the lie: mentira. Mentiroso = liar.","Isso é mentira, eu vi tudo!","That's a lie, I saw everything!"],
["apresentar","","to introduce / to present","ah-preh-zen-TAHR","FALSO","Means to present, but also to INTRODUCE someone. 'Introduzir' sounds rude here; it means to insert.","Quero te apresentar minha namorada.","I want to introduce you to my girlfriend."],
["interessado","","interested","een-teh-reh-SAH-doo","EN","interested → interessado: -ed becomes -ado.","Ela está interessada no curso.","She's interested in the course."],
["agradecer","","to thank","ah-grah-deh-SEHR","PAD","agradar (to please) → agradecer: to show you're pleased. Obrigado is the thank-you itself.","Quero agradecer a todos pela ajuda.","I want to thank everyone for the help."],
["endereço","m","address","en-deh-REH-soo","PAD","en + direção: the direction you're sent in. Brazil says endereço; Portugal says morada.","Qual é o seu endereço?","What's your address?"],
["mapa","m","map","MAH-pah","EN","map → mapa. Masculine despite the -a, like o dia and o problema.","Olha o mapa do metrô.","Look at the subway map."],
["enfermeira","f","nurse","en-fehr-MAY-rah","EN","infirmary → enfermeira: she works in the infirmary. Enfermeiro for a man.","A enfermeira mediu a minha pressão.","The nurse took my blood pressure."],
["visitar","","to visit","vee-zee-TAHR","EN","visit → visitar. Visitar is for places and people alike.","Quero visitar o Pantanal um dia.","I want to visit the Pantanal one day."],
["aguentar","","to stand / to bear / to hold on","ah-gwen-TAHR","SOM","\"AH, GWEN, I can't stand it!\" Não aguento mais = I can't take it anymore.","Não aguento mais esse calor.","I can't stand this heat anymore."],
["aberto","","open","ah-BEHR-too","PAD","abrir (to open) → aberto. Shop signs: ABERTO / FECHADO.","A padaria está aberta até as nove.","The bakery is open until nine."],
["lar","m","home","LAHR","LA","Lares were the Roman household gods guarding the home: lar. Lar, doce lar = home sweet home.","Lar, doce lar!","Home, sweet home!"],
["instante","m","instant / moment","eens-TAHN-chee","EN","instant → instante. Um instante! = One moment!","Espera um instante, já volto.","Wait a moment, I'll be right back."],
["leste","m","east","LES-chee","SOM","Picture a compass: L for leste on the right, O for oeste on the left. Zona Leste is São Paulo's east side.","Ele mora na zona leste da cidade.","He lives on the east side of the city."],
["usado","","used / second-hand","oo-ZAH-doo","EN","used → usado. Carro usado = used car.","Comprei um carro usado.","I bought a used car."],
["familiar","","family (adj.) / familiar","fah-mee-lee-AHR","EN","family → familiar: almoço familiar = family lunch. Also familiar, as in English.","Esse rosto me parece familiar.","That face looks familiar to me."],
["parecido","","similar / alike","pah-reh-SEE-doo","PAD","parecer (to seem) → parecido: things that seem the same. Parecido com = similar to.","Você é muito parecido com seu pai.","You look a lot like your dad."],
["desligar","","to turn off / to hang up","jeez-lee-GAHR","PAD","des- (un-) + ligar (to turn on, to call): to switch off or hang up.","Desliga a luz quando sair.","Turn off the light when you leave."],
["preocupar","","to worry","preh-oh-koo-PAHR","EN","preoccupy → preocupar. Não se preocupe! = Don't worry!","Não se preocupe, vai dar tudo certo.","Don't worry, everything will be fine."],
["primo","m","cousin","PREE-moo","IMG","Your PRIME playmate at family gatherings: your primo. Prima for a girl.","Meu primo mora em Curitiba.","My cousin lives in Curitiba."],
["pedaço","m","piece / bit","peh-DAH-soo","SOM","PEDAL a bike to the bakery and grab a piece of cake: pedaço.","Quer um pedaço de bolo?","Want a piece of cake?"],
["jardim","m","garden","zhahr-JEENG (nasal)","FR","jardin (French) → jardim. Same root as yard and garden.","Minha mãe cuida do jardim.","My mom takes care of the garden."],
["segredo","m","secret","seh-GREH-doo","EN","secret → segredo: c becomes g, t becomes d. Guarda segredo? = Can you keep a secret?","Posso te contar um segredo?","Can I tell you a secret?"],
["ovo","m","egg","OH-voo","LA","ovum (Latin) → ovo, as in oval and ovulation: egg-shaped.","Quero um ovo frito, por favor.","I'd like a fried egg, please."],
["café da manhã","m","breakfast","kah-FEH dah mah-NYAH (nasal)","PAD","Literally 'coffee of the morning'. Portugal says pequeno-almoço; Brazil says café da manhã.","O café da manhã está incluído?","Is breakfast included?"],
["melhorar","","to improve / to get better","meh-lyoh-RAHR","LA","melior (Latin, better) → melhorar, as in ameliorate. Melhoras! = Get well soon!","Seu português melhorou muito!","Your Portuguese has improved a lot!"],
["membro","m","member","MEM-broo","EN","member → membro. The B moved: memb-ER → memb-RO.","Ele é membro do clube.","He's a member of the club."],
["camisa","f","shirt","kah-MEE-zah","EN","chemise → camisa. Camisa do Brasil = the yellow soccer jersey.","Ele usa camisa social no trabalho.","He wears a dress shirt at work."],
["viajar","","to travel","vee-ah-ZHAHR","EN","voyage → viajar. Boa viagem! = Have a good trip!","Adoro viajar de carro.","I love traveling by car."],
["sonhar","","to dream","soh-NYAHR","LA","somnus (Latin, sleep) → sonho, sonhar: what you do while asleep. Sonhar com = to dream about.","Sonhei com você ontem.","I dreamed about you last night."],
["útil","","useful","OO-chew","EN","utility → útil. Dia útil = business day.","Esse aplicativo é muito útil.","This app is very useful."],
["massa","f","dough / pasta / mass","MAH-sah","EN","mass → massa. Pasta, dough and cake batter are all massa. Slang: massa! = awesome!","A massa da pizza está pronta.","The pizza dough is ready."],
["jamais","","never (ever)","zhah-MYES","FR","jamais (French) → jamais. Stronger than nunca: jamais! = never ever!","Jamais vou esquecer aquele dia.","I'll never forget that day."],
["falso","","false / fake","FOW-soo","EN","false → falso. Nota falsa = counterfeit bill.","Isso é verdadeiro ou falso?","Is this true or false?"],
["vencer","","to win / to beat / to expire","ven-SEHR","LA","vincere (Latin) → vencer, as in invincible. Also to expire: o leite venceu.","O Brasil venceu a partida.","Brazil won the match."],
["neve","f","snow","NEH-vee","LA","nix, nivis (Latin) → neve. Sierra Nevada = snowy mountain range.","Nunca vi neve na vida.","I've never seen snow in my life."],
["aviso","m","warning / notice","ah-VEE-zoo","EN","advise / advisory → aviso. Aviso prévio = notice period at work.","Tem um aviso na porta.","There's a notice on the door."],
["nascer","","to be born / to rise (sun)","nah-SEHR","EN","nascent / native → nascer. Nasci em 1990 = I was born in 1990. Nascer do sol = sunrise.","Onde você nasceu?","Where were you born?"],
["sábado","m","Saturday","SAH-bah-doo","EN","Sabbath → sábado: the day of rest. Brazil's weekdays are numbered, but Saturday kept its name.","No sábado vamos à praia.","On Saturday we're going to the beach."],
["bairro","m","neighborhood","BYE-hoo","SOM","Say BYE to the city center and head home to your bairro.","Meu bairro é tranquilo.","My neighborhood is quiet."],
["completo","","complete / full","kohm-PLEH-too","EN","complete → completo. Hotel completo = fully booked.","O formulário não está completo.","The form isn't complete."],
["tratamento","m","treatment","trah-tah-MEN-too","EN","treatment → tratamento: -ment becomes -mento.","O tratamento dura três meses.","The treatment lasts three months."],
["vazio","","empty","vah-ZEE-oo","EN","void / vacuum → vazio. Estômago vazio = empty stomach.","A geladeira está vazia.","The fridge is empty."],
["companheiro","m","companion / partner","kohm-pah-NYAY-roo","EN","companion → companheiro: someone you share bread with. Often a life partner.","Ela foi com o companheiro dela.","She went with her partner."],
["quieto","","quiet / still","kee-EH-too","EN","quiet → quieto. Fica quieto! = Keep still! / Be quiet!","Fica quieto um minuto, por favor.","Keep still for a minute, please."],
["discurso","m","speech","jees-KOOR-soo","EN","discourse → discurso. Fazer um discurso = to give a speech.","O discurso do noivo foi lindo.","The groom's speech was beautiful."],
["chocolate","m","chocolate","shoh-koh-LAH-chee","EN","chocolate → chocolate, same spelling, but CH = sh and the final -te = 'chee'.","Quero um sorvete de chocolate.","I want a chocolate ice cream."],
["salário","m","salary / wages","sah-LAH-ree-oo","EN","salary → salário. Roman soldiers were paid in sal (salt): sal → salário.","Recebo o salário no dia cinco.","I get my salary on the fifth."],
["prédio","m","building","PREH-jee-oo","IMG","A tall, proud building on a PRAIRIE: prédio. Everyday word for a block of flats.","Moro no décimo andar do prédio.","I live on the tenth floor of the building."],
["caça","f","hunt / hunting","KAH-sah","PAD","caçar (to hunt) → caça. Caça ao tesouro = treasure hunt.","As crianças adoram caça ao tesouro.","Kids love treasure hunts."],
["bolsa","f","bag / purse / scholarship","BOHL-sah","FALSO","Not a bolster: bolsa is a handbag. Bolsa de estudos = scholarship; Bolsa de Valores = stock exchange.","Esqueci a bolsa no táxi!","I left my purse in the taxi!"],
["amar","","to love","ah-MAHR","LA","amare (Latin) → amar: amorous, amateur (someone who does it for love).","Eu te amo muito.","I love you so much."],
["guardar","","to keep / to put away / to save","gwahr-DAHR","EN","guard → guardar: keep it safe. Guardar dinheiro = to save money.","Guarda os brinquedos na caixa.","Put the toys away in the box."],
["montanha","f","mountain","mohn-TAH-nyah","EN","mountain → montanha. Montanha-russa (Russian mountain) = roller coaster.","Subimos a montanha a pé.","We climbed the mountain on foot."],
["fraco","","weak","FRAH-koo","SOM","A FRAgile cup is weak: fraco. Café fraco = weak coffee.","O sinal do wi-fi está fraco.","The wi-fi signal is weak."],
["modelo","m","model","moh-DEH-loo","EN","model → modelo. Works for fashion models and car models alike.","Qual é o modelo do seu celular?","What's your phone model?"],
["chuva","f","rain","SHOO-vah","SOM","SHOO! the rain away: chuva. Chover = to rain; guarda-chuva = umbrella.","Vai ter chuva à tarde.","There will be rain in the afternoon."],
["ciência","f","science","see-EN-see-ah","EN","science → ciência: -ence becomes -ência.","Ela gosta de ciência e matemática.","She likes science and math."],
["pão","m","bread","POWN (nasal)","LA","panis (Latin) → pão: pantry, companion (bread-sharer). Pão francês = Brazil's daily roll.","Comprei pão quentinho na padaria.","I bought warm bread at the bakery."],
["dente","m","tooth","DEN-chee","EN","dentist / dental → dente. Escovar os dentes = to brush your teeth.","Preciso ir ao dentista, meu dente dói.","I need to see the dentist, my tooth hurts."],
["exame","m","exam / medical test","eh-ZAH-mee","EN","exam → exame. In Brazil, also a medical test: exame de sangue = blood test.","Amanhã faço um exame de sangue.","Tomorrow I'm getting a blood test."],
["lavar","","to wash","lah-VAHR","EN","lavatory / lavender (used in washing) → lavar. Lavar a louça = to do the dishes.","Quem vai lavar a louça hoje?","Who's doing the dishes today?"],
["zero","m","zero","ZEH-roo","EN","zero → zero. Zero a zero = nil-nil. Carro zero = brand-new car.","O jogo terminou zero a zero.","The game ended zero to zero."],
["suco","m","juice","SOO-koo","SOM","You SUCK juice through a straw: suco. Portugal says sumo; Brazil says suco.","Um suco de laranja, por favor.","An orange juice, please."],
["impressão","f","impression / printing","eem-preh-SOWN (nasal)","REGRA","impression → impressão: -ssion becomes -ssão. Also printing: impressora = printer.","Tive uma boa impressão dele.","I got a good impression of him."],
["piloto","m","pilot / racing driver","pee-LOH-too","EN","pilot → piloto. Brazil loves its Formula 1 pilotos, like Senna.","O piloto anunciou a aterrissagem.","The pilot announced the landing."],
["princípio","m","principle / beginning","preen-SEE-pee-oo","EN","principle → princípio. A princípio = at first; em princípio = in principle.","A princípio, achei o curso difícil.","At first, I thought the course was hard."],
["esquina","f","street corner","es-KEE-nah","SOM","On the corner, you ESKEE-nah around the turn on your skates. Na esquina = on the corner.","A farmácia fica na esquina.","The pharmacy is on the corner."],
["intenção","f","intention","een-ten-SOWN (nasal)","REGRA","intention → intenção. -tion becomes -ção. Sem intenção = unintentionally.","Não foi minha intenção te magoar.","It wasn't my intention to hurt you."],
["curso","m","course","KOOR-soo","EN","course → curso. Curso de inglês = English course; also a college major.","Fiz um curso de culinária.","I took a cooking course."],
["domingo","m","Sunday","doh-MEEN-goo","LA","dies Dominicus (Latin, the Lord's day) → domingo. Brazil's day for family lunch.","No domingo, almoçamos na casa da vó.","On Sunday, we have lunch at grandma's."],
["nota","f","grade / note / bill","NOH-tah","EN","note → nota. A school grade, a musical note, and a banknote: nota de cem.","Tirei nota dez na prova!","I got a ten on the test!"],
["entrevista","f","interview","en-treh-VEES-tah","EN","interview → entrevista: entre (inter) + vista (view), piece by piece.","Tenho uma entrevista de emprego hoje.","I have a job interview today."],
["recentemente","","recently","heh-sen-chee-MEN-chee","REGRA","recent + -mente = recently. Long word, simple rule.","Ele se mudou recentemente.","He moved recently."],
["entretanto","","however / meanwhile","en-treh-TAHN-too","PAD","entre (between) + tanto: in between all that. Formal; in speech, Brazilians say mas or só que.","O plano é bom; entretanto, é caro.","The plan is good; however, it's expensive."],
["queijo","m","cheese","KAY-zhoo","LA","caseus (Latin) → queijo, like casein. Pão de queijo is Minas Gerais's famous cheese bread.","Adoro pão de queijo quentinho.","I love warm cheese bread."],
["juntar","","to gather / to join / to save up","zhoon-TAHR","EN","join / joint → juntar. Juntar dinheiro = to save up money.","Estou juntando dinheiro para viajar.","I'm saving money to travel."],
["compreender","","to understand / to comprehend","kohm-pree-en-DEHR","EN","comprehend → compreender. A bit more formal than entender.","Compreendo a sua preocupação.","I understand your concern."],
["honesto","","honest","oh-NES-too","EN","honest → honesto. The H is silent in both languages.","Ele é um homem honesto.","He's an honest man."],
["artigo","m","article","ahr-CHEE-goo","EN","article → artigo. Also a grammar article: o, a.","Li um artigo interessante hoje.","I read an interesting article today."],
["gelado","","ice-cold / chilled","zheh-LAH-doo","IT","gelato (Italian) → gelado. Brazilians want their beer bem gelada.","Uma cerveja bem gelada, por favor.","A really cold beer, please."],
["extra","","extra","ES-trah","EN","extra → extra, same word. The X sounds like S here. Hora extra = overtime.","Fiz duas horas extras hoje.","I did two hours of overtime today."],
["vizinho","m","neighbor","vee-ZEE-nyoo","LA","vicinus (Latin) → vizinho, as in vicinity: the people in your vicinity.","O vizinho de cima é muito barulhento.","The upstairs neighbor is very noisy."],
["lição","f","lesson","lee-SOWN (nasal)","REGRA","lesson → lição. Lição de casa = homework. Aprendi a lição!","Aprendi a lição: nunca mais faço isso.","I learned my lesson: never doing that again."],
["fila","f","line / queue","FEE-lah","IMG","People in single FILE: a fila. Brazil has lines for everything, even at the bakery.","A fila do banco está enorme.","The line at the bank is huge."],
["vestir","","to dress / to put on","ves-CHEER","EN","vest / vestment → vestir. Vestido = dress.","Vou vestir uma roupa mais leve.","I'm going to put on lighter clothes."],
["garota","f","girl","gah-ROH-tah","NOME","\"Garota de Ipanema\" (The Girl from Ipanema), the famous bossa nova song.","Aquela garota é minha irmã.","That girl is my sister."],
["piscina","f","swimming pool","pee-SEE-nah","LA","piscis (Latin, fish) → piscina: originally a fish pond.","As crianças estão na piscina.","The kids are in the pool."],
["oferecer","","to offer","oh-feh-reh-SEHR","EN","offer → oferecer. Posso te oferecer um café?","Posso te oferecer um café?","Can I offer you a coffee?"],
["ensinar","","to teach","en-see-NAHR","EN","insignia / sign → ensinar: to show the signs. Ensinar alguém a fazer algo.","Minha avó me ensinou a cozinhar.","My grandma taught me to cook."],
["trocar","","to change / to exchange / to swap","troh-KAHR","SOM","TRUCK-ar your stuff: you load it up and trade it. Trocar de roupa = to change clothes.","Posso trocar essa camisa?","Can I exchange this shirt?"],
["diversão","f","fun / amusement","jee-vehr-SOWN (nasal)","EN","diversion → diversão: a fun diversion. Parque de diversões = amusement park.","A viagem foi pura diversão.","The trip was pure fun."],
["adorar","","to love / to adore","ah-doh-RAHR","EN","adore → adorar. Brazilians use it all the time: adorei! = I loved it!","Adorei o seu cabelo novo!","I loved your new hair!"],
["incêndio","m","fire (blaze)","een-SEN-jee-oo","EN","incendiary → incêndio: a fire that destroys. A cooking flame is fogo.","O incêndio destruiu a fábrica.","The fire destroyed the factory."],
["felicidade","f","happiness","feh-lee-see-DAH-jee","REGRA","felicity → felicidade (-ty → -dade). Feliz = happy.","Felicidade é estar com a família.","Happiness is being with family."],
["compartilhar","","to share","kohm-pahr-chee-LYAHR","PAD","com (with) + partilhar (to split): to share. Portugal says partilhar; Brazil says compartilhar.","Compartilhei o vídeo no grupo.","I shared the video in the group."],
["localização","f","location","loh-kah-lee-zah-SOWN (nasal)","REGRA","localization → localização. Manda a localização! = Send me your location!","Me manda a sua localização.","Send me your location."],
["regra","f","rule","HEH-grah","LA","regula (Latin) → regra, as in regular and regulation.","Em casa, a regra é tirar o sapato.","At home, the rule is to take your shoes off."],
["menor","","smaller / younger / minor","meh-NOHR","EN","minor → menor. Menor de idade = underage.","Meu irmão menor tem dez anos.","My younger brother is ten."],
["virar","","to turn / to become","vee-RAHR","EN","veer → virar: veer right. Vira à direita = turn right. Also to become: virou médico.","Vira à esquerda no semáforo.","Turn left at the traffic light."],
["álcool","m","alcohol","OW-koh-ow","EN","alcohol → álcool. Also the fuel: Brazilian cars run on álcool (ethanol).","Não bebo álcool.","I don't drink alcohol."],
["adivinhar","","to guess","ah-jee-vee-NYAHR","EN","divine → adivinhar: a diviner guesses the future. Adivinha! = Guess what!","Adivinha quem eu encontrei hoje!","Guess who I ran into today!"],
["carteira","f","wallet / ID card","kahr-TAY-rah","PAD","cartão (card) + -eira: the thing that holds the cards. Carteira de motorista = driver's license.","Perdi a carteira com todos os documentos.","I lost my wallet with all my documents."],
["telefonar","","to phone / to call","teh-leh-foh-NAHR","EN","telephone → telefonar. In everyday Brazil, ligar is more common.","Vou telefonar para o médico.","I'm going to call the doctor."],
["famoso","","famous","fah-MOH-zoo","REGRA","famous → famoso: -ous becomes -oso.","Esse restaurante é famoso pela feijoada.","This restaurant is famous for its feijoada."],
["atender","","to answer (phone) / to serve","ah-ten-DEHR","FALSO","Not to attend! Atender is to answer the phone or serve a customer. To attend is frequentar or assistir.","Pode atender o telefone, por favor?","Can you answer the phone, please?"],
["passagem","f","ticket (travel) / passage","pah-SAH-zheng","REGRA","passage → passagem: -age becomes -agem. The ticket that buys your passage.","Comprei a passagem para Recife.","I bought the ticket to Recife."],
["gordo","","fat","GOHR-doo","IMG","A big GOURD sitting on the table: gordo. Brazilians use it affectionately too.","O gato ficou gordo de tanto comer.","The cat got fat from eating so much."],
["sentar","","to sit (down)","sen-TAHR","SOM","SIT and get CENTERED: sentar. Senta aqui! = Sit here!","Pode sentar, fique à vontade.","Have a seat, make yourself at home."],
["roubar","","to steal / to rob","hoh-BAHR","EN","rob → roubar. Initial R is a breathy H: 'hoh-BAHR'.","Roubaram minha bicicleta!","Someone stole my bike!"],
["suficiente","","enough / sufficient","soo-fee-see-EN-chee","EN","sufficient → suficiente. Já é suficiente, obrigado = That's enough, thanks.","Temos comida suficiente para todos.","We have enough food for everyone."],
["barato","","cheap","bah-RAH-too","SOM","A BARGAIN at the market: barato. Opposite of caro.","Esse mercado é mais barato.","This store is cheaper."],
["talento","m","talent","tah-LEN-too","EN","talent → talento. -ent becomes -ento.","Ela tem talento para música.","She has a talent for music."],
["página","f","page","PAH-zhee-nah","EN","page → página. The stress is on the first syllable: PAH-zhee-nah.","Abram o livro na página dez.","Open your books to page ten."],
["identificação","f","identification / ID","ee-den-chee-fee-kah-SOWN (nasal)","REGRA","identification → identificação. The longest -tion/-ção you'll meet today.","Preciso ver sua identificação.","I need to see your ID."],
["chateado","","upset / annoyed","shah-chee-AH-doo","SOM","Someone CHATTED behind your back and now you're upset: chateado.","Fiquei chateado com o que ele disse.","I got upset about what he said."],
["nojento","","disgusting / gross","noh-ZHEN-too","SOM","\"NO! GENTLE...\" you say, backing away from something gross: nojento. Nojo = disgust.","Esse banheiro está nojento.","This bathroom is disgusting."],
["artista","m","artist","ahr-CHEES-tah","EN","artist → artista. Same form for a man or woman: o artista, a artista.","Ele é um artista de rua.","He's a street artist."],
["terreno","m","plot of land / terrain","teh-HEH-noo","EN","terrain → terreno. Comprar um terreno = to buy a plot of land.","Compraram um terreno na praia.","They bought a plot of land at the beach."],
["experimentar","","to try (on, out) / to taste","es-peh-ree-men-TAHR","FALSO","Not only to experiment: it's to try something out. Experimentar uma roupa = to try on clothes.","Posso experimentar esse vestido?","Can I try on this dress?"],
["permitir","","to allow / to permit","pehr-mee-CHEER","EN","permit → permitir. É permitido? = Is it allowed?","Não é permitido fumar aqui.","Smoking isn't allowed here."],
["brincadeira","f","joke / game / play","breen-kah-DAY-rah","FRASE","\"É brincadeira!\" = Just kidding! Brincar is what kids do: play.","Calma, foi só uma brincadeira!","Relax, it was just a joke!"],
["canto","m","corner / singing","KAHN-too","PAD","Two meanings: cantar → canto (singing), and the corner of a room. Fica no canto = stay in the corner.","Coloca a planta no canto da sala.","Put the plant in the corner of the room."],
["atravessar","","to cross","ah-trah-veh-SAHR","EN","traverse → atravessar. Atravessar a rua = to cross the street.","Cuidado ao atravessar a rua.","Be careful crossing the street."],
["bruxa","f","witch","BROO-shah","IMG","A witch flying on her BRUSH-broom: bruxa. X sounds like sh.","A bruxa do filme dava medo.","The witch in the movie was scary."],
["aluno","m","student / pupil","ah-LOO-noo","EN","alumnus → aluno: the M fell away. Aluna for a girl.","O professor tem trinta alunos.","The teacher has thirty students."],
["bando","m","gang / flock / bunch","BAHN-doo","EN","band (group) → bando. Um bando de = a bunch of.","Um bando de pássaros passou voando.","A flock of birds flew by."],
["trânsito","m","traffic","TRAHN-zee-too","EN","transit → trânsito. São Paulo's trânsito is legendary.","O trânsito hoje está parado.","Traffic is at a standstill today."],
["correio","m","mail / post office","koh-HAY-oo","EN","courier → correio. Correios is Brazil's postal service.","Mandei o pacote pelo correio.","I sent the package by mail."],
["carregar","","to carry / to charge (battery)","kah-heh-GAHR","EN","carry / cargo → carregar. Also to charge your phone: carregar o celular.","Preciso carregar o celular.","I need to charge my phone."],
["estragar","","to ruin / to spoil / to break","es-trah-GAHR","SOM","A STRAY GAR-den hose floods the lawn and ruins it: estragar. Comida estragada = spoiled food.","A chuva estragou o piquenique.","The rain ruined the picnic."],
["queda","f","fall / drop","KEH-dah","PAD","cair (to fall) → queda. Queda de energia = power outage.","Houve uma queda de energia ontem.","There was a power outage yesterday."],
["arroz","m","rice","ah-HOHS","SOM","\"AH, HOSE down that rice!\" Arroz e feijão: rice and beans, the Brazilian everyday plate.","Arroz e feijão todo dia, sem falta.","Rice and beans every day, without fail."],
["pó","m","dust / powder","POH (open o)","SOM","Blow on a dusty shelf: \"POH!\" Café em pó = ground coffee.","Os móveis estão cheios de pó.","The furniture is covered in dust."],
["teatro","m","theater","chee-AH-troo","EN","theater → teatro. Brazilian T before 'e' in an unstressed syllable becomes 'chee'.","Vamos ao teatro no sábado.","We're going to the theater on Saturday."],
["período","m","period","peh-REE-oh-doo","EN","period → período. Período da manhã = morning shift.","Estudo no período da noite.","I study in the evening shift."],
["enganar","","to fool / to deceive","en-gah-NAHR","SOM","An ENGINE salesman fools you with a bad car: enganar. Me enganei = I was wrong.","Não tente me enganar!","Don't try to fool me!"],
["planejar","","to plan","plah-neh-ZHAHR","EN","plan → planejar. Portugal writes planear; Brazil says planejar.","Estamos planejando uma viagem.","We're planning a trip."],
["calmo","","calm","KOW-moo","EN","calm → calmo. Final L sounds like W, so 'KOW-moo'. Calma! = Relax!","O mar está calmo hoje.","The sea is calm today."],
["bravo","","angry / mad / fierce","BRAH-voo","FALSO","Not brave! In Brazil, bravo means angry: minha mãe ficou brava. A cão bravo is a fierce dog.","Minha mãe ficou brava comigo.","My mom got mad at me."],
["aumentar","","to increase / to turn up","ow-men-TAHR","EN","augment → aumentar. Aumenta o som! = Turn up the music!","Aumenta o volume, essa música é boa!","Turn up the volume, this song is good!"],
["erva","f","herb / grass","EHR-vah","EN","herb → erva: the H is gone. Erva-mate is the herb for chimarrão.","Coloca erva-doce no chá.","Put fennel in the tea."],
["retirar","","to remove / to withdraw / to pick up","heh-chee-RAHR","EN","retire / retract → retirar. Retirar dinheiro = to withdraw money.","Preciso retirar a encomenda no correio.","I need to pick up the package at the post office."],
["somente","","only","soh-MEN-chee","PAD","só (only) + -mente: a formal 'only'. In speech, just say só.","Somente funcionários podem entrar.","Only employees may enter."],
["promessa","f","promise","proh-MEH-sah","EN","promise → promessa. Cumprir a promessa = to keep the promise.","Promessa é dívida.","A promise is a debt."],
["inverno","m","winter","een-VEHR-noo","LA","hibernus (Latin) → inverno, as in hibernate: the animals sleep through it.","No inverno, o Sul pode ter geada.","In winter, the South can get frost."],
["fumaça","f","smoke","foo-MAH-sah","EN","fume → fumaça. Fumar = to smoke; Portugal says fumo, Brazil fumaça.","Tem fumaça saindo da cozinha!","There's smoke coming out of the kitchen!"],
["rosa","","pink / rose","HOH-zah","IMG","A ROSE is pink: rosa means both the flower and the color. Initial R is a breathy H.","Ela pintou o quarto de rosa.","She painted the room pink."],
["garoto","m","boy / kid","gah-ROH-too","PAD","The male partner of garota. Common in São Paulo; menino is everywhere.","O garoto chutou a bola longe.","The boy kicked the ball far."],
["revista","f","magazine","heh-VEES-tah","EN","review → revista: a magazine reviews the news. Also a police search: revista policial.","Li isso numa revista.","I read that in a magazine."],
["elevador","m","elevator","eh-leh-vah-DOHR","EN","elevator → elevador: -tor becomes -dor.","O elevador está quebrado.","The elevator is broken."],
["rato","m","rat / mouse","HAH-too","EN","rat → rato. Brazilians use it for both rat and mouse. Initial R = breathy H.","Vi um rato na garagem!","I saw a rat in the garage!"],
["obra","f","work / construction site","OH-brah","EN","opera / opus → obra: a work of art or a construction project. Em obras = under construction.","A rua está em obras.","The street is under construction."],
["bicicleta","f","bicycle","bee-see-KLEH-tah","EN","bicycle → bicicleta. Casual: a bike.","Vou de bicicleta para o trabalho.","I bike to work."],
["vidro","m","glass (material)","VEE-droo","LA","vitrum (Latin) → vidro, as in vitreous. The material only: drinking glass is copo.","Cuidado, a mesa é de vidro.","Careful, the table is made of glass."],
["saudável","","healthy","sow-DAH-vew","PAD","saúde (health) + -ável: health-able. Comida saudável = healthy food.","Estou tentando comer mais saudável.","I'm trying to eat healthier."],
["quantidade","f","quantity / amount","kwahn-chee-DAH-jee","REGRA","quantity → quantidade (-ty → -dade).","Que quantidade de comida!","What an amount of food!"],
["repetir","","to repeat","heh-peh-CHEER","EN","repeat → repetir. Pode repetir? = Can you say that again? Also to take seconds of food.","Pode repetir mais devagar?","Can you repeat that more slowly?"],
["conto","m","short story / tale","KOHN-too","PAD","contar (to tell) → conto: a story told. Conto de fadas = fairy tale.","Minha avó contava contos de fadas.","My grandmother used to tell fairy tales."],
["turno","m","shift / round","TOOR-noo","EN","turn → turno: your turn at work, a shift. Segundo turno = runoff election.","Ela trabalha no turno da noite.","She works the night shift."],
["cozinhar","","to cook","koh-zee-NYAHR","PAD","cozinha (kitchen) → cozinhar: what you do in the kitchen. Cozinheiro = cook.","Meu pai cozinha muito bem.","My dad cooks really well."],
["nação","f","nation","nah-SOWN (nasal)","REGRA","nation → nação: -tion becomes -ção, and the T disappears.","O Brasil é uma nação enorme.","Brazil is a huge nation."],
["calado","","quiet / silent","kah-LAH-doo","SOM","Someone CALLED out to him, but he stayed calado, not saying a word. Calar a boca = to shut up.","Por que você está tão calado?","Why are you so quiet?"],
["biblioteca","f","library","bee-blee-oh-TEH-kah","FALSO","Not a bookstore (that's livraria)! biblio (book) + teca (case): the place to borrow books.","Estudo na biblioteca depois da aula.","I study at the library after class."],
["estudo","m","study","es-TOO-doo","PAD","estudar (to study) → estudo. Also a studio apartment in some places.","O estudo mostrou bons resultados.","The study showed good results."],
["escuridão","f","darkness","es-koo-ree-DOWN (nasal)","PAD","escuro (dark) + -idão (-ness): darkness. Same pattern as solidão = solitude.","Ele tem medo da escuridão.","He's afraid of the dark."],
["vaca","f","cow","VAH-kah","LA","vacca (Latin) → vaca, and vaccine: the first vaccine came from cowpox.","A vaca está pastando no campo.","The cow is grazing in the field."],
["nadar","","to swim","nah-DAHR","SOM","\"NADA? Nothing to fear!\" you shout, jumping in to swim: nadar.","Você sabe nadar?","Do you know how to swim?"],
["jogador","m","player","zhoh-gah-DOHR","PAD","jogar (to play) + -dor (-er): player. Jogador de futebol = soccer player.","Ele é jogador do Flamengo.","He's a Flamengo player."],
["esporte","m","sport","es-POHR-chee","EN","sport → esporte: E before SP, and the final -te sounds like 'chee'.","Qual é o seu esporte favorito?","What's your favorite sport?"],
["gostoso","","tasty / delicious","gohs-TOH-zoo","PAD","gosto (taste) + -oso (-ous): taste-ous. Que gostoso! = So good!","Esse bolo está muito gostoso.","This cake is really tasty."],
["reputação","f","reputation","heh-poo-tah-SOWN (nasal)","REGRA","reputation → reputação: -tion becomes -ção.","O restaurante tem ótima reputação.","The restaurant has a great reputation."],
["sono","m","sleep / sleepiness","SOH-noo","LA","somnus (Latin) → sono, as in insomnia. Estou com sono = I'm sleepy.","Estou com muito sono hoje.","I'm really sleepy today."],
["oceano","m","ocean","oh-see-AH-noo","EN","ocean → oceano. Oceano Atlântico, all along Brazil's coast.","O oceano estava muito agitado.","The ocean was very rough."],
["fita","f","tape / ribbon","FEE-tah","IMG","A ribbon tied to FIT around a present: fita. Fita adesiva = sticky tape. Bahia's fitinhas are wish ribbons.","Amarrei uma fita no presente.","I tied a ribbon on the present."],
["compra","f","purchase / shopping","KOHM-prah","PAD","comprar (to buy) → compra. Fazer compras = to go shopping.","Fiz uma compra pela internet.","I made a purchase online."],
["motorista","m","driver","moh-toh-REES-tah","PAD","motor + -ista: the motor person. Motorista de ônibus = bus driver.","O motorista do ônibus foi gentil.","The bus driver was kind."],
["devolver","","to return (give back)","deh-vohw-VEHR","EN","devolve (to pass back) → devolver. Devolve meu livro! = Give my book back!","Preciso devolver o livro na biblioteca.","I need to return the book to the library."],
["superfície","f","surface","soo-pehr-FEE-see-ee","EN","surface → superfície: super (on top) + face. The stress lands on FEE.","A superfície da mesa está molhada.","The table's surface is wet."],
["ponta","f","tip / point / end","POHN-tah","EN","point → ponta: the pointy tip. Ponta do nariz = tip of the nose.","O nome dele está na ponta da língua!","His name is on the tip of my tongue!"],
["empregado","m","employee / servant","em-preh-GAH-doo","EN","employed → empregado: the employed one. Emprego = job.","A empresa tem cem empregados.","The company has a hundred employees."],
["jogada","f","move / play (in a game)","zhoh-GAH-dah","PAD","jogar (to play) → jogada: one play or move. Que jogada! = What a move!","Que jogada incrível do atacante!","What an amazing play by the striker!"],
["organização","f","organization","ohr-gah-nee-zah-SOWN (nasal)","REGRA","organization → organização. -zation becomes -zação.","Ela trabalha numa organização de saúde.","She works at a health organization."],
["açúcar","m","sugar","ah-SOO-kahr","SOM","\"A SUGAR!\" Say it fast with a Brazilian accent and you've got açúcar. Sem açúcar = no sugar.","Café sem açúcar, por favor.","Coffee without sugar, please."],
["pássaro","m","bird","PAH-sah-roo","LA","passer (Latin, sparrow) → pássaro: the passerine birds. Ave is the formal word.","Um pássaro fez ninho na janela.","A bird built a nest on the window."],
["meia-noite","f","midnight","may-ah-NOY-chee","PAD","meia (half) + noite (night): the middle of the night, midnight.","A festa vai até meia-noite.","The party goes until midnight."],
["doente","","sick / ill","doh-EN-chee","PAD","doer (to hurt) → doente: someone things hurt for. Ficar doente = to get sick.","Não fui trabalhar, estou doente.","I didn't go to work, I'm sick."],
["pausa","f","pause / break","POW-zah","EN","pause → pausa. Fazer uma pausa = to take a break.","Vamos fazer uma pausa para o café.","Let's take a coffee break."],
["tarefa","f","task / chore / homework","tah-REH-fah","SOM","A TARIFF of chores: every family member pays with a tarefa. Tarefa de casa = homework.","Cada um tem uma tarefa em casa.","Everyone has a chore at home."],
["sopa","f","soup","SOH-pah","EN","soup → sopa. Sopa de legumes = vegetable soup. É sopa! = It's a piece of cake!","Uma sopa quente é ótima no frio.","A hot soup is great in the cold."],
["abrigo","m","shelter","ah-BREE-goo","SOM","A BRIGADE of firefighters builds a shelter: abrigo. Abrigo de animais = animal shelter.","Adotamos o cachorro num abrigo.","We adopted the dog from a shelter."],
["telefonema","m","phone call","teh-leh-foh-NEH-mah","PAD","telefone + -ema, like problema: masculine despite the -a. Ligação is the everyday word.","Recebi um telefonema estranho.","I got a strange phone call."],
["sobremesa","f","dessert","soh-bree-MEH-zah","PAD","sobre (over, after) + mesa (table): what comes after the meal at the table.","De sobremesa, tem pudim.","For dessert, there's flan."],
["sujo","","dirty","SOO-zhoo","SOM","A pig in SOOT-y mud is sujo. The opposite of limpo.","Tira esse tênis sujo daqui!","Get those dirty sneakers out of here!"],
["anúncio","m","ad / announcement","ah-NOON-see-oo","EN","announce → anúncio. Anúncio na TV = TV commercial.","Vi um anúncio de emprego no jornal.","I saw a job ad in the newspaper."],
["fio","m","wire / thread","FEE-oo","LA","filum (Latin) → fio, as in filament and file (a line). Fio dental = dental floss.","Cuidado com o fio no chão.","Watch out for the wire on the floor."],
["prato","m","plate / dish","PRAH-too","EN","platter / plate → prato. Prato do dia = dish of the day.","O prato do dia é feijoada.","Today's special is feijoada."],
["engano","m","mistake / wrong number","en-GAH-noo","PAD","enganar (to fool) → engano. On the phone: foi engano = wrong number.","Desculpa, foi engano.","Sorry, wrong number."],
["evento","m","event","eh-VEN-too","EN","event → evento: -ent becomes -ento.","O evento começa às sete.","The event starts at seven."],
["chato","","boring / annoying","SHAH-too","FALSO","Not chatty, and not flat (in Portugal it can be)! In Brazil, chato is boring or annoying. Que chato! = What a drag!","Esse filme é muito chato.","This movie is really boring."],
["papai","m","daddy","pah-PIE","SOM","Like 'papa' with a little PIE at the end: papai. Papai Noel = Santa Claus.","Papai, me dá um abraço!","Daddy, give me a hug!"],
["sujeito","m","guy / subject","soo-ZHAY-too","EN","subject → sujeito: the grammar subject. Casually, a guy: um sujeito estranho.","Um sujeito estranho perguntou por você.","A strange guy asked for you."],
["limpeza","f","cleaning / cleanliness","leem-PEH-zah","PAD","limpo (clean) + -eza (-ness): cleanness. Faxina is the big house cleaning.","Hoje é dia de limpeza geral.","Today is general cleaning day."],
["produção","f","production","proh-doo-SOWN (nasal)","REGRA","production → produção: -tion becomes -ção again.","A produção de café caiu este ano.","Coffee production fell this year."],
["museu","m","museum","moo-ZEH-oo","EN","museum → museu: the -m drops and the ending glides. Museu do Amanhã in Rio.","O museu fecha às segundas.","The museum is closed on Mondays."],
["raça","f","race / breed","HAH-sah","EN","race → raça. Also a dog breed: cachorro de raça = purebred dog.","Que raça é o seu cachorro?","What breed is your dog?"],
["declaração","f","declaration / statement","deh-klah-rah-SOWN (nasal)","REGRA","declaration → declaração. Declaração de amor = love confession.","Ele fez uma declaração de amor.","He made a declaration of love."],
["significado","m","meaning","seeg-nee-fee-KAH-doo","EN","significance → significado: what a word signifies.","Qual é o significado dessa palavra?","What's the meaning of this word?"],
["seção","f","section / department","seh-SOWN (nasal)","REGRA","section → seção. Brazil drops the C that Portugal keeps (secção).","A seção de frutas fica no fundo.","The fruit section is at the back."],
["galinha","f","hen / chicken","gah-LEE-nyah","LA","gallina (Latin) → galinha: the gallinaceous birds. The live bird; frango is the meat.","A galinha botou um ovo.","The hen laid an egg."],
["amizade","f","friendship","ah-mee-ZAH-jee","PAD","amigo (friend) + -dade (-ship): friendship. Amity is the English cousin.","Nossa amizade começou na escola.","Our friendship started at school."],
["popular","","popular","poh-poo-LAHR","EN","popular → popular, same spelling. Also 'working-class': bairro popular.","Esse cantor é muito popular no Nordeste.","This singer is very popular in the Northeast."],
["sexta-feira","f","Friday","SES-tah FAY-rah","REGRA","sexta = sixth: Friday is day six counting from Sunday. Sextou! = TGIF!","Sexta-feira tem happy hour.","There's happy hour on Friday."],
["negativo","","negative","neh-gah-CHEE-voo","EN","negative → negativo. Also slang for 'no way': negativo!","O resultado do teste deu negativo.","The test result came back negative."],
["cobertura","f","topping / penthouse / coverage","koh-behr-TOO-rah","EN","cover → cobertura. Bolo com cobertura de chocolate; also the top-floor penthouse.","O bolo tem cobertura de chocolate.","The cake has chocolate frosting."],
["frango","m","chicken (meat)","FRAHN-goo","SOM","A FRYING chicken: frango. On the menu it's always frango; galinha is the live hen.","Frango grelhado com salada, por favor.","Grilled chicken with salad, please."],
["falhar","","to fail","fah-LYAHR","EN","fail → falhar. Lh sounds like 'lli' in million.","O motor falhou na subida.","The engine failed on the climb."],
["concerto","m","concert","kohn-SEHR-too","EN","concert → concerto. Usually classical; a pop concert is a show.","Fomos a um concerto de piano.","We went to a piano concert."],
["privada","f","toilet (bowl)","pree-VAH-dah","EN","privy → privada: the private place. Brazilian word for the toilet itself.","A privada está entupida.","The toilet is clogged."],
["sal","m","salt","SOW","LA","sal (Latin) → sal: salad, salary, saline. Final L sounds like W.","Passa o sal, por favor.","Pass the salt, please."],
["cargo","m","position / post (job)","KAHR-goo","FALSO","Not cargo (that's carga)! Um cargo is a job title: cargo de gerente = manager position.","Ela assumiu o cargo de diretora.","She took the position of director."],
["documento","m","document / ID","doh-koo-MEN-too","EN","document → documento. Brazilians say documento for any ID: posso ver um documento?","Posso ver um documento com foto?","Can I see a photo ID?"],
["e-mail","m","email","ee-MAY-oo","EN","email → e-mail, borrowed whole. Brazilians pronounce it 'ee-MAY-oo'.","Te mando um e-mail amanhã.","I'll send you an email tomorrow."],
["show","m","show / concert","SHOH","EN","show → show, borrowed from English. In Brazil, any live gig: show do Caetano. Show de bola! = Awesome!","Vamos ao show do Gilberto Gil?","Shall we go to the Gilberto Gil concert?"],
["faca","f","knife","FAH-kah","SOM","\"FAH-kah!\" A knife chopping down hard on the cutting board.","Cuidado, essa faca está afiada.","Careful, that knife is sharp."],
["feio","","ugly","FAY-oo","SOM","\"FIE! O, how ugly!\" says a Shakespeare character: feio. Feia for a woman.","Esse prédio é muito feio.","This building is really ugly."],
["assistir","","to watch / to attend","ah-sees-CHEER","FALSO","Not to assist! Assistir means to watch: assistir TV. To help is ajudar.","Vamos assistir um filme hoje?","Shall we watch a movie today?"],
["firme","","firm / steady","FEER-mee","EN","firm → firme. Tudo firme? = Everything good? (casual greeting).","Segura firme na corda.","Hold on tight to the rope."],
["igualmente","","likewise / equally","ee-gwow-MEN-chee","FRASE","\"Bom fim de semana!\" \"Igualmente!\" = Same to you! igual + -mente.","Prazer em conhecer! Igualmente!","Nice to meet you! Likewise!"],
["identificar","","to identify","ee-den-chee-fee-KAHR","EN","identify → identificar: -ify becomes -ificar.","A polícia conseguiu identificar o ladrão.","The police managed to identify the thief."],
["cobra","f","snake","KOH-brah","EN","cobra → cobra: in Portuguese it means ANY snake, not just the cobra. The word came to English from Portuguese.","Vi uma cobra na trilha!","I saw a snake on the trail!"],
["exercício","m","exercise","eh-zehr-SEE-see-oo","EN","exercise → exercício. For both the gym and the homework.","Faço exercício três vezes por semana.","I exercise three times a week."],
["vila","f","village / small neighborhood","VEE-lah","EN","village / villa → vila. In Brazilian cities, a vila is a small residential lane or neighborhood.","Ele cresceu numa vila de pescadores.","He grew up in a fishing village."],
["fresco","","fresh / cool","FRES-koo","EN","fresh → fresco. Peixe fresco = fresh fish. Slang: fresco = fussy, picky.","O peixe aqui é sempre fresco.","The fish here is always fresh."],
["refeição","f","meal","heh-fay-SOWN (nasal)","EN","refection (old English for a meal) → refeição: food that 'refreshes' you.","O almoço é a principal refeição do dia.","Lunch is the main meal of the day."],
["produto","m","product","proh-DOO-too","EN","product → produto: -ct becomes -to.","Esse produto está em promoção.","This product is on sale."],
["sócio","m","partner (business) / member","SOH-see-oo","EN","associate / social → sócio. Sócio do clube = club member.","Ele é meu sócio na empresa.","He's my partner in the company."],
["barulho","m","noise","bah-ROO-lyoo","SOM","A BARREL rolling down the stairs makes a lot of barulho. Barulhento = noisy.","Que barulho é esse lá fora?","What's that noise outside?"],
["quebrar","","to break","keh-BRAHR","SOM","A KEBAB skewer snaps in two: quebrar. Quebrou! = It broke!","O copo caiu e quebrou.","The glass fell and broke."],
["tinta","f","paint / ink","CHEEN-tah","EN","tint → tinta: color you put on. Both wall paint and pen ink.","A tinta da parede ainda está molhada.","The paint on the wall is still wet."],
["sorrir","","to smile","soh-HEER","PAD","sub (under) + rir (laugh): a little laugh under the breath. Sorriso = smile.","Ela sorriu quando me viu.","She smiled when she saw me."],
["estudante","m","student","es-too-DAHN-chee","EN","student → estudante. Same form for both sexes: o estudante, a estudante.","Tenho desconto de estudante.","I have a student discount."],
["caminhar","","to walk","kah-mee-NYAHR","PAD","caminho (path) → caminhar: to go along the path. Great for a morning stroll.","Gosto de caminhar na orla de manhã.","I like walking along the seafront in the morning."],
["flor","f","flower","FLOHR","EN","flower / floral / Florida → flor.","Ele me deu uma flor no aniversário.","He gave me a flower on my birthday."],
["caneta","f","pen","kah-NEH-tah","IMG","A CANE-shaped pen leaning on your notebook: caneta.","Me empresta uma caneta?","Can you lend me a pen?"],
["praticar","","to practice","prah-chee-KAHR","EN","practice → praticar. Preciso praticar meu português!","Preciso praticar mais meu português.","I need to practice my Portuguese more."],
["cachorro","m","dog","kah-SHOH-hoo","FALSO","A Spanish speaker hears 'puppy'; in Brazil cachorro is any dog. Cachorro-quente = hot dog!","Meu cachorro adora passear.","My dog loves going for walks."],
["ruim","","bad","hoo-EEN (nasal)","EN","ruin → ruim: something ruined is bad. Nada mal is 'not bad'.","Esse café está ruim.","This coffee is bad."],
["sapato","m","shoe","sah-PAH-too","SOM","A SAP-stained shoe after a walk in the woods: sapato. Sapataria = shoe store.","Esse sapato está apertado.","This shoe is too tight."],
["maçã","f","apple","mah-SAHN (nasal)","SOM","\"MA, SAN-dra ate my apple!\" Maçã do rosto = cheekbone.","Como uma maçã todo dia.","I eat an apple every day."],
["fruta","f","fruit","FROO-tah","EN","fruit → fruta. Brazil has frutas you've never heard of: jabuticaba, cupuaçu.","Qual é sua fruta preferida?","What's your favorite fruit?"],
["dirigir","","to drive / to direct","jee-ree-ZHEER","EN","direct → dirigir: to direct a car or a film. Portugal says conduzir; Brazil says dirigir.","Você sabe dirigir?","Do you know how to drive?"],
["odiar","","to hate","oh-jee-AHR","EN","odious → odiar. Ódio = hatred.","Vou odiar acordar cedo amanhã.","I am going to hate waking up early tomorrow."],
["escutar","","to listen","es-koo-TAHR","SOM","A SCOUT listens carefully in the woods: escutar. Escuta! = Listen!","Escuta essa música, é linda.","Listen to this song, it's beautiful."],
["trem","m","train","TRENG (nasal)","EN","train → trem. Portugal says comboio; Brazil says trem. In Minas, trem also means 'thing'!","O trem para Santos sai às nove.","The train to Santos leaves at nine."],
["banheiro","m","bathroom / restroom","bah-NYAY-roo","PAD","banho (bath) + -eiro: the bath place. Onde fica o banheiro? is a must-know.","Onde fica o banheiro?","Where's the bathroom?"],
["traduzir","","to translate","trah-doo-ZEER","LA","traducere (Latin, lead across) → traduzir: you lead words across languages. Tradução = translation.","Pode traduzir essa frase para mim?","Can you translate this sentence for me?"],
["colher","f","spoon","koh-LYEHR (open e)","PAD","Same spelling as colher (to harvest, 'koh-LYEHR' with closed e)! The noun spoon has an open e.","Me passa uma colher para a sopa.","Pass me a spoon for the soup."],
["soletrar","","to spell","soh-leh-TRAHR","PAD","só (only) + letra (letter): only letters, one at a time. Pode soletrar? = Can you spell it?","Pode soletrar o seu sobrenome?","Can you spell your last name?"],
["idioma","m","language","ee-jee-OH-mah","EN","idiom → idioma: a full language, not just an expression. Masculine despite the -a.","Quantos idiomas você fala?","How many languages do you speak?"]
];
